insert into public.therapist_resources (slug, title, kind, summary, goal, audience, duration, body_md, fields, tags, created_at)
values
  ('support-system-map', 'Support System Map', 'worksheet'::resource_kind, 'A visual map of the people, groups and resources a client can draw on when things get hard.', 'Use it to help the client see their support network as wider than it feels day to day.', array['Adults', 'Teens']::text[], '20 minutes', 'Draw concentric circles in session, closest people nearest the center, and let the client place each name themselves rather than suggesting who belongs where. A map with an empty inner circle is itself useful information, not a failure to fix. Revisit it every few months, since support networks shift, and keep a copy the client can add to on their own.', '[{"id": "f0", "type": "textarea", "label": "People I can call for practical help"}, {"id": "f1", "type": "textarea", "label": "People I can call just to talk"}, {"id": "f2", "type": "textarea", "label": "Groups or communities I am part of"}, {"id": "f3", "type": "textarea", "label": "Professionals and services I can reach"}, {"id": "f4", "type": "textarea", "label": "One relationship I would like to grow"}, {"id": "f5", "type": "textarea", "label": "One name I keep leaving off this map and why"}]'::jsonb, array['support network', 'resources', 'social connection']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('weekly-self-care-inventory', 'Weekly Self-Care Inventory', 'worksheet'::resource_kind, 'Checks a week against basic physical, social and restorative needs rather than mood alone.', 'Use it to catch neglected basics before they show up as a crisis.', array['Adults']::text[], '10 minutes weekly', 'Run through it at the start of a session as a quick scan rather than a test to pass. Sleep, food, movement, sunlight, social contact and rest each get a plain yes or a note, no scoring. A pattern of the same box going unchecked week after week is more informative than any single week. Use it to open conversation about what is realistic to change first.', '[{"id": "f0", "type": "textarea", "label": "Sleep this week"}, {"id": "f1", "type": "textarea", "label": "Meals and eating patterns"}, {"id": "f2", "type": "textarea", "label": "Movement or activity"}, {"id": "f3", "type": "textarea", "label": "Time outdoors or in daylight"}, {"id": "f4", "type": "textarea", "label": "Contact with other people"}, {"id": "f5", "type": "textarea", "label": "Rest and downtime"}, {"id": "f6", "type": "textarea", "label": "One thing I will protect next week"}]'::jsonb, array['self-care', 'basic needs', 'monitoring']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('time-use-audit-worksheet', 'Time Use Audit Worksheet', 'worksheet'::resource_kind, 'A log of how a typical day actually goes, hour by hour, compared with how the client wishes it went.', 'Use it to find the gap between intended time and actual time without guilt.', array['Adults', 'Teens']::text[], 'One week', 'Have the client fill it in at the end of each day rather than trying to predict the day in advance, since memory of a day is more honest after it than before. Look together for the hours that vanish and where they tend to go. The point is information, not a verdict on how the week should have gone. Use the pattern to plan one small, specific change for next week.', '[{"id": "f0", "type": "textarea", "label": "How I spent this morning"}, {"id": "f1", "type": "textarea", "label": "How I spent this afternoon"}, {"id": "f2", "type": "textarea", "label": "How I spent this evening"}, {"id": "f3", "type": "textarea", "label": "What I meant to do instead"}, {"id": "f4", "type": "textarea", "label": "What got in the way"}, {"id": "f5", "type": "textarea", "label": "One change I want to try next week"}]'::jsonb, array['time management', 'planning', 'self-monitoring']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('motivation-and-barriers-ladder', 'Motivation and Barriers Ladder', 'worksheet'::resource_kind, 'Ranks a client''s readiness to change a specific behavior alongside the obstacles in the way.', 'Use it to separate willingness from ability so each can be addressed on its own terms.', array['Adults', 'Teens']::text[], '20 minutes', 'Ask for a number from zero to ten for how much the client wants the change, then a separate number for how confident they are they could do it if they decided to. A gap between the two numbers points to where the work actually is: low want needs a different conversation than low confidence. List barriers next to each rung rather than at the bottom, so the client can see what stands between them and the next step up.', '[{"id": "f0", "type": "textarea", "label": "The change I am considering"}, {"id": "f1", "type": "textarea", "label": "How much I want this, zero to ten"}, {"id": "f2", "type": "textarea", "label": "How confident I am I could do it, zero to ten"}, {"id": "f3", "type": "textarea", "label": "What is in the way"}, {"id": "f4", "type": "textarea", "label": "What would move my confidence up one point"}, {"id": "f5", "type": "textarea", "label": "What would move my want up one point"}]'::jsonb, array['motivation', 'readiness', 'change']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('session-takeaways-summary-sheet', 'Session Takeaways Summary Sheet', 'worksheet'::resource_kind, 'A short sheet a client fills out at the end of a session to capture what mattered before it fades.', 'Use it to make sure the week''s insight survives the walk to the car.', array['Adults', 'Teens', 'Groups']::text[], 'Five minutes', 'Leave the last five minutes of session for it rather than assigning it as homework, since what feels obvious in the room is often gone by the next day. One line each is enough; resist the urge to make the client write an essay. Keep it in a running document so a client can flip back through weeks and see their own thread.', '[{"id": "f0", "type": "textarea", "label": "The main thing we talked about today"}, {"id": "f1", "type": "textarea", "label": "What I understood that I did not before"}, {"id": "f2", "type": "textarea", "label": "One thing I want to try this week"}, {"id": "f3", "type": "textarea", "label": "One question I still have"}]'::jsonb, array['session structure', 'reflection', 'between sessions']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('downward-arrow-worksheet', 'Downward Arrow Worksheet', 'cbt'::resource_kind, 'Follows one automatic thought down through what it would mean, and mean again, to find the belief underneath.', 'Use it to reach the core belief driving a surface-level worry.', array['Adults', 'Teens']::text[], '25 minutes', 'Start from a single specific thought and ask what it would mean if it were true, then ask that question again of the answer, three or four times. Slow down when the client''s affect shifts; that is usually where the real belief sits. Write each answer down as they say it rather than summarizing, so the client can see their own chain rather than the clinician''s paraphrase.', '[{"id": "f0", "type": "textarea", "label": "The thought I started with"}, {"id": "f1", "type": "textarea", "label": "If that were true, what would it mean? (1)"}, {"id": "f2", "type": "textarea", "label": "If that were true, what would it mean? (2)"}, {"id": "f3", "type": "textarea", "label": "If that were true, what would it mean? (3)"}, {"id": "f4", "type": "textarea", "label": "The belief I landed on"}, {"id": "f5", "type": "textarea", "label": "How long I think I have carried this belief"}]'::jsonb, array['core beliefs', 'thinking traps', 'downward arrow']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('put-the-thought-on-trial', 'Put the Thought on Trial', 'cbt'::resource_kind, 'Casts a sticky thought as the defendant and gathers evidence for and against it like a courtroom exhibit.', 'Use it to weigh a thought''s evidence with more structure than a plain thought record allows.', array['Adults', 'Teens']::text[], '20 minutes', 'Assign the thought a formal charge, such as ''I am a failure,'' and build two witness lists, one for the prosecution and one for the defense, using only facts a stranger could verify rather than feelings. A verdict of not proven is a legitimate outcome and often more honest than a clean acquittal. Keep the tone playful; the structure does the work, not the drama.', '[{"id": "f0", "type": "textarea", "label": "The thought on trial"}, {"id": "f1", "type": "textarea", "label": "Evidence for the prosecution (facts only)"}, {"id": "f2", "type": "textarea", "label": "Evidence for the defense (facts only)"}, {"id": "f3", "type": "textarea", "label": "What a fair judge would say"}, {"id": "f4", "type": "textarea", "label": "My verdict"}, {"id": "f5", "type": "textarea", "label": "A fairer, more accurate thought"}]'::jsonb, array['thought record', 'evidence', 'cognitive restructuring']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('best-friend-self-talk-technique', 'Best Friend Self-Talk Technique', 'cbt'::resource_kind, 'Compares what a client tells themselves with what they would tell a friend in the same spot.', 'Use it to surface a harsher standard the client holds only for themselves.', array['Adults', 'Teens']::text[], '15 minutes', 'Ask the client to write down exactly what they said to themselves, then imagine a close friend in the identical situation and write what they would actually say to that friend. The gap between the two columns is usually the whole session. Ask directly why the friend deserves gentler words, and let the client sit with their own answer rather than supplying one.', '[{"id": "f0", "type": "textarea", "label": "The situation"}, {"id": "f1", "type": "textarea", "label": "What I said to myself"}, {"id": "f2", "type": "textarea", "label": "What I would say to a friend in this exact spot"}, {"id": "f3", "type": "textarea", "label": "What is different about the two"}, {"id": "f4", "type": "textarea", "label": "What I am willing to try saying to myself instead"}]'::jsonb, array['self-criticism', 'self-compassion', 'self-talk']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('graded-task-assignment-planner', 'Graded Task Assignment Planner', 'cbt'::resource_kind, 'Breaks a task the client has been avoiding into a ladder of steps small enough that the first one feels easy.', 'Use it to build momentum on a stalled task through small, achievable wins.', array['Adults', 'Teens']::text[], '20 minutes', 'Start from the smallest version of the task the client can imagine doing today, even if it looks trivial, and only add a rung once the one below it is comfortable. Rate difficulty and mood before and after each step to make progress visible. A client who cannot picture the smallest step yet needs it broken down further, not encouragement to push through.', '[{"id": "f0", "type": "textarea", "label": "The task I have been avoiding"}, {"id": "f1", "type": "textarea", "label": "Step 1 (smallest possible version)"}, {"id": "f2", "type": "textarea", "label": "Step 2"}, {"id": "f3", "type": "textarea", "label": "Step 3"}, {"id": "f4", "type": "textarea", "label": "Step 4"}, {"id": "f5", "type": "textarea", "label": "Difficulty rating before starting"}, {"id": "f6", "type": "textarea", "label": "How it actually went"}]'::jsonb, array['behavioral activation', 'avoidance', 'task initiation']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('evidence-for-and-against-worksheet', 'Evidence For and Against Worksheet', 'cbt'::resource_kind, 'A two-column sheet weighing the facts that support a thought against the facts that do not.', 'Use it to slow down a thought long enough to test it against the record.', array['Adults', 'Teens']::text[], '15 minutes', 'Keep both columns to observable facts rather than feelings or predictions, and push back gently when an entry is really an interpretation in disguise. An uneven sheet, heavy on one side, is itself worth noticing out loud. Close by asking the client to write a conclusion that fits the evidence rather than the original thought.', '[{"id": "f0", "type": "textarea", "label": "The thought I am testing"}, {"id": "f1", "type": "textarea", "label": "Evidence for this thought"}, {"id": "f2", "type": "textarea", "label": "Evidence against this thought"}, {"id": "f3", "type": "textarea", "label": "What a neutral observer would conclude"}, {"id": "f4", "type": "textarea", "label": "A conclusion that fits the evidence"}]'::jsonb, array['thought record', 'evidence', 'cognitive restructuring']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('leaves-on-a-stream-practice', 'Leaves on a Stream Practice', 'act'::resource_kind, 'A guided visualization for placing each passing thought on a leaf and watching it float away.', 'Use it to build a felt sense of watching thoughts rather than being pulled into them.', array['Adults', 'Teens']::text[], 'Ten minutes', 'Guide it slowly in session first so the client has a model before trying it alone. Some clients cannot picture a stream; a conveyor belt or passing cars works just as well, so let them choose their own image. The goal is not an empty mind but a client noticing when they have climbed onto a leaf, and stepping back off.', '[{"id": "f0", "type": "textarea", "label": "What the exercise was like for me"}, {"id": "f1", "type": "textarea", "label": "A thought that showed up"}, {"id": "f2", "type": "textarea", "label": "How long I stayed with it before noticing"}, {"id": "f3", "type": "textarea", "label": "The image I want to use next time"}]'::jsonb, array['defusion', 'mindfulness', 'core ACT']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('passengers-on-the-bus-exercise', 'Passengers on the Bus Exercise', 'act'::resource_kind, 'A metaphor for driving toward a valued direction while loud, unhelpful thoughts ride along as passengers.', 'Use it to separate what a client does from what their thoughts are shouting at them.', array['Adults', 'Teens']::text[], '20 minutes', 'Name the loudest passengers with the client, in their own words, and let the passengers be as rude as they actually are rather than softened for the worksheet. Ask what direction the client would drive if the passengers had no vote. Practice noticing a passenger''s voice getting louder without pulling over to negotiate with it.', '[{"id": "f0", "type": "textarea", "label": "My loudest passengers, in their own words"}, {"id": "f1", "type": "textarea", "label": "What they usually convince me to do"}, {"id": "f2", "type": "textarea", "label": "The direction I want to drive anyway"}, {"id": "f3", "type": "textarea", "label": "One thing I did this week despite a passenger''s noise"}]'::jsonb, array['defusion', 'values', 'committed action']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('unwelcome-party-guest-metaphor', 'Unwelcome Party Guest Metaphor', 'act'::resource_kind, 'Casts a painful feeling as a guest who showed up uninvited but does not have to run the party.', 'Use it to build willingness to host a hard feeling without letting it take over.', array['Adults', 'Teens']::text[], '15 minutes', 'Ask what the client usually does when this guest arrives, whether that is throwing them out, hiding in another room, or handing them the microphone. Explore what it would look like to let the guest stay in a corner while the party, meaning the client''s life, keeps going. This is not about liking the guest, only about not rearranging the whole evening around them.', '[{"id": "f0", "type": "textarea", "label": "The feeling that shows up uninvited"}, {"id": "f1", "type": "textarea", "label": "What I usually do when it arrives"}, {"id": "f2", "type": "textarea", "label": "What the party looks like when this guest takes over"}, {"id": "f3", "type": "textarea", "label": "What the party could look like with the guest just present"}]'::jsonb, array['acceptance', 'willingness', 'emotions']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('willingness-thermometer-practice', 'Willingness Thermometer Practice', 'act'::resource_kind, 'Rates a client''s willingness to feel a difficult emotion, separate from how much they like feeling it.', 'Use it to track willingness as its own skill, distinct from comfort or mood.', array['Adults', 'Teens']::text[], 'Ten minutes', 'Ask the client to rate willingness from zero to ten before an exercise or exposure step and again afterward, and note that willingness can rise even when discomfort does not fall. Some clients confuse willingness with wanting to feel the emotion; clarify that willingness only means making room for it. Track the number over several sessions rather than judging any one reading.', '[{"id": "f0", "type": "textarea", "label": "The feeling or situation"}, {"id": "f1", "type": "textarea", "label": "Willingness before, zero to ten"}, {"id": "f2", "type": "textarea", "label": "Willingness after, zero to ten"}, {"id": "f3", "type": "textarea", "label": "What made it move, if it moved"}, {"id": "f4", "type": "textarea", "label": "What I noticed about the difference between willing and wanting"}]'::jsonb, array['willingness', 'acceptance', 'committed action']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('polygraph-metaphor-worksheet', 'Polygraph Metaphor Worksheet', 'act'::resource_kind, 'Treats a self-critical thought as a lie detector that is wired wrong and reads calm as guilty.', 'Use it to question the accuracy of a thought''s alarm rather than the client''s character.', array['Adults', 'Teens']::text[], '15 minutes', 'Ask the client to describe the alarm a thought sets off and whether that alarm has ever been wrong before. A polygraph wired to flag any sign of nervousness will convict an innocent person every time, and a mind wired the same way will do the same to its owner. Use the metaphor to build distance from the thought''s verdict, not to argue the thought out of existence.', '[{"id": "f0", "type": "textarea", "label": "The thought that acts like an alarm"}, {"id": "f1", "type": "textarea", "label": "What sets the alarm off"}, {"id": "f2", "type": "textarea", "label": "A time the alarm was wrong before"}, {"id": "f3", "type": "textarea", "label": "What I want to do even while the alarm is going off"}]'::jsonb, array['defusion', 'cognitive fusion', 'core ACT']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('radical-acceptance-practice-card', 'Radical Acceptance Practice Card', 'dbt'::resource_kind, 'Walks a client through accepting a painful reality they cannot currently change, step by step.', 'Use it to reduce the suffering added on top of pain by fighting a fact that will not move.', array['Adults', 'Teens']::text[], '15 minutes', 'Distinguish clearly between acceptance and approval; accepting a fact is not agreeing it is fine. Have the client name the reality in one plain sentence, then notice where in the body the fighting shows up. Acceptance is rarely a single moment, so frame it as a practice returned to many times rather than a box checked once.', '[{"id": "f0", "type": "textarea", "label": "The reality I am fighting"}, {"id": "f1", "type": "textarea", "label": "What fighting it costs me"}, {"id": "f2", "type": "textarea", "label": "One plain sentence that names the reality"}, {"id": "f3", "type": "textarea", "label": "Where I feel the resistance in my body"}, {"id": "f4", "type": "textarea", "label": "What accepting this does not mean"}]'::jsonb, array['radical acceptance', 'distress tolerance']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('distress-tolerance-accepts-skills-card', 'Distress Tolerance ACCEPTS Skills Card', 'dbt'::resource_kind, 'Walks through the ACCEPTS distraction skills for getting through a crisis moment without making it worse.', 'Use it to give a client a menu of distraction skills ready before the next crisis moment.', array['Adults', 'Teens']::text[], '15 minutes', 'Go through Activities, Contributing, Comparisons, Emotions, Pushing away, Thoughts and Sensations with the client and fill in a real option for each rather than leaving any blank. These are distraction skills for surviving a moment, not for solving the underlying problem, and it helps to say that plainly. Have the client keep the finished card somewhere they can reach quickly.', '[{"id": "f0", "type": "textarea", "label": "Activities I can turn to"}, {"id": "f1", "type": "textarea", "label": "Ways I can contribute or help someone else"}, {"id": "f2", "type": "textarea", "label": "A comparison that puts this in perspective"}, {"id": "f3", "type": "textarea", "label": "A different emotion I can generate on purpose"}, {"id": "f4", "type": "textarea", "label": "A way to push the situation away for now"}, {"id": "f5", "type": "textarea", "label": "A thought or sensation I can use to ground"}]'::jsonb, array['distress tolerance', 'ACCEPTS', 'crisis']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('behavioral-chain-analysis-card', 'Behavioral Chain Analysis Card', 'dbt'::resource_kind, 'Traces a difficult behavior backward, link by link, from the vulnerability that set it up to the outcome.', 'Use it to find the earliest link where a different choice was possible.', array['Adults', 'Teens']::text[], '30 minutes', 'Start from the behavior itself and work backward through the prompting event, the vulnerability factors, and every link of thought, feeling and action in between, resisting the pull to jump straight to a solution. The earliest links are usually the most changeable, so spend real time there rather than rushing to the end. Close by naming one link the client is willing to practice doing differently.', '[{"id": "f0", "type": "textarea", "label": "The behavior"}, {"id": "f1", "type": "textarea", "label": "The prompting event"}, {"id": "f2", "type": "textarea", "label": "Vulnerability factors that day (sleep, hunger, stress)"}, {"id": "f3", "type": "textarea", "label": "Thoughts, feelings and actions, in order"}, {"id": "f4", "type": "textarea", "label": "The consequences"}, {"id": "f5", "type": "textarea", "label": "The earliest link I could change"}, {"id": "f6", "type": "textarea", "label": "What I will practice instead at that link"}]'::jsonb, array['chain analysis', 'target behavior', 'self-monitoring']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('emotion-mind-vs-wise-mind-sorting-card', 'Emotion Mind vs Wise Mind Sorting Card', 'dbt'::resource_kind, 'Sorts a set of recent decisions by whether they came from emotion mind, reasonable mind or wise mind.', 'Use it to build a client''s own working sense of what wise mind feels like for them.', array['Adults', 'Teens']::text[], '15 minutes', 'List a handful of recent decisions and sort each one honestly rather than aiming for a good score; a card that is all wise mind is probably not being honest. Ask what wise mind physically feels like for this client specifically, since the description varies from person to person. Use the pattern to catch, next time, which mind is driving before the decision is made.', '[{"id": "f0", "type": "textarea", "label": "Decision 1 and which mind it came from"}, {"id": "f1", "type": "textarea", "label": "Decision 2 and which mind it came from"}, {"id": "f2", "type": "textarea", "label": "Decision 3 and which mind it came from"}, {"id": "f3", "type": "textarea", "label": "What wise mind feels like in my body"}, {"id": "f4", "type": "textarea", "label": "A decision coming up where I want to check in with wise mind first"}]'::jsonb, array['wise mind', 'mindfulness', 'decision-making']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('self-soothe-kit-planner', 'Self-Soothe Kit Planner', 'dbt'::resource_kind, 'Plans a physical kit of five-senses items a client assembles ahead of time for a hard moment.', 'Use it to make self-soothing a kit that is ready, not a skill invented from scratch under stress.', array['Adults', 'Teens']::text[], '20 minutes', 'Go sense by sense, sight, sound, smell, taste and touch, and pick one real, obtainable item for each rather than an idea the client will never actually buy. A kit that lives in a bag by the door gets used; a kit that lives only on paper does not. Revisit it after it has been used once or twice and swap out anything that did not help.', '[{"id": "f0", "type": "textarea", "label": "Sight item"}, {"id": "f1", "type": "textarea", "label": "Sound item"}, {"id": "f2", "type": "textarea", "label": "Smell item"}, {"id": "f3", "type": "textarea", "label": "Taste item"}, {"id": "f4", "type": "textarea", "label": "Touch item"}, {"id": "f5", "type": "textarea", "label": "Where this kit will actually live"}]'::jsonb, array['self-soothe', 'distress tolerance', 'five senses']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('love-languages-discovery-sheet', 'Love Languages Discovery Sheet', 'couples'::resource_kind, 'Has both partners independently rank how they prefer to give and receive affection, then compare.', 'Use it to surface a mismatch in how affection is offered versus how it lands.', array['Couples']::text[], '25 minutes', 'Have each partner rank the options alone before comparing, so one does not simply mirror the other. The interesting finding is usually the gap between how a partner prefers to give affection and how they prefer to receive it, since people tend to give the way they wish to receive. Ask each partner to try one thing on the other''s list this week and report back.', '[{"id": "f0", "type": "textarea", "label": "How I most like to receive affection"}, {"id": "f1", "type": "textarea", "label": "How I tend to show affection to my partner"}, {"id": "f2", "type": "textarea", "label": "What surprised me about my partner''s ranking"}, {"id": "f3", "type": "textarea", "label": "One thing I will try this week"}]'::jsonb, array['Gottman', 'affection', 'communication']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('conflict-repair-menu-card', 'Conflict Repair Menu Card', 'couples'::resource_kind, 'A shared list of specific repair attempts, written in advance, that this couple knows tends to work.', 'Use it to give a couple options ready before they are mid-argument and cannot think of any.', array['Couples']::text[], '20 minutes', 'Build the list together, in session, from repair attempts that have actually worked for this couple before rather than generic suggestions. A short phrase, a hand signal or even a specific word can be on the menu alongside longer repairs. Agree in advance that either partner can reach for the menu mid-conflict without it being read as giving up the argument.', '[{"id": "f0", "type": "textarea", "label": "A repair attempt that has worked for us before"}, {"id": "f1", "type": "textarea", "label": "Another one"}, {"id": "f2", "type": "textarea", "label": "A signal either of us can use to call for a repair"}, {"id": "f3", "type": "textarea", "label": "What we agree the signal means when it is used"}, {"id": "f4", "type": "textarea", "label": "One repair we want to add to our menu"}]'::jsonb, array['repair', 'conflict', 'Gottman']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('partner-check-in-ritual-planner', 'Partner Check-In Ritual Planner', 'couples'::resource_kind, 'Designs a short, recurring check-in ritual for a couple to actually keep, not just intend.', 'Use it to turn a plan to talk more into a specific, repeatable habit.', array['Couples']::text[], '20 minutes', 'Push for specifics: a day, a time, a location and a length the couple will actually protect, since a vague plan to check in more rarely survives a busy week. Agree on three or four questions the ritual will always include, so neither partner has to invent an agenda under pressure. Review after a few weeks and adjust the length or questions rather than abandoning the ritual at the first missed week.', '[{"id": "f0", "type": "textarea", "label": "When and where this check-in will happen"}, {"id": "f1", "type": "textarea", "label": "How long it will last"}, {"id": "f2", "type": "textarea", "label": "A question we will always ask each other"}, {"id": "f3", "type": "textarea", "label": "Another question we will always ask"}, {"id": "f4", "type": "textarea", "label": "What we will do if we miss a week"}]'::jsonb, array['communication', 'ritual', 'connection']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('shared-calendar-alignment-worksheet', 'Shared Calendar Alignment Worksheet', 'couples'::resource_kind, 'Compares each partner''s sense of a shared week against the actual calendar to find quiet conflict.', 'Use it to catch scheduling friction before it turns into an unspoken grievance.', array['Couples']::text[], '20 minutes', 'Have each partner describe what they expect the coming week to look like before comparing it to the actual calendar; the gap between expectation and schedule is often where resentment starts. Look specifically for whose plans quietly take priority when the week gets tight. Agree on one change to how the couple plans together going forward, not just this week''s fix.', '[{"id": "f0", "type": "textarea", "label": "What I expect this week to look like"}, {"id": "f1", "type": "textarea", "label": "What my partner expects this week to look like"}, {"id": "f2", "type": "textarea", "label": "Where our expectations do not match the calendar"}, {"id": "f3", "type": "textarea", "label": "Whose plans tend to give way when the week is tight"}, {"id": "f4", "type": "textarea", "label": "One change to how we plan together"}]'::jsonb, array['scheduling', 'fairness', 'communication']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('physical-affection-preferences-map', 'Physical Affection Preferences Map', 'couples'::resource_kind, 'Maps each partner''s comfort and preference for different kinds of everyday physical affection.', 'Use it to make assumptions about touch explicit instead of guessed at.', array['Couples']::text[], '20 minutes', 'Go through everyday forms of touch, a hand on the back, a hug at the door, sitting close on the couch, and have each partner mark how welcome each one feels day to day, since welcome can shift with stress or mood. Note that a preference can be true generally and still not apply on a hard day. Use the map to open a conversation about checking in, not as a fixed contract.', '[{"id": "f0", "type": "textarea", "label": "Forms of touch I welcome most days"}, {"id": "f1", "type": "textarea", "label": "Forms of touch that depend on my mood"}, {"id": "f2", "type": "textarea", "label": "What tells my partner I am not in the mood for touch right now"}, {"id": "f3", "type": "textarea", "label": "How I want my partner to check before initiating on a hard day"}]'::jsonb, array['affection', 'boundaries', 'communication']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('feelings-thermometer-craft', 'Feelings Thermometer Craft', 'kids'::resource_kind, 'A child builds a paper thermometer that slides from calm to overwhelmed to name their own intensity.', 'Use it to give a child a hands-on way to show how big a feeling is, not just name it.', array['Children']::text[], '20 minutes', 'The parent helps color and cut the thermometer while the child decides what each level looks and sounds like in their own words. Keep the top level concrete: what does this child specifically do at the very top, and what helps bring the slider back down. Post it somewhere the child can point to it instead of finding words in the moment.', '[{"id": "f0", "type": "textarea", "label": "What calm looks like for me (bottom of the thermometer)"}, {"id": "f1", "type": "textarea", "label": "What a medium feeling looks like"}, {"id": "f2", "type": "textarea", "label": "What the very top looks like for me"}, {"id": "f3", "type": "textarea", "label": "One thing that helps bring me back down"}]'::jsonb, array['emotion identification', 'children', 'regulation']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('my-team-of-helpers-poster', 'My Team of Helpers Poster', 'kids'::resource_kind, 'A child draws and names the adults on their team, and what each one helps with.', 'Use it to help a child locate who to go to for which kind of help.', array['Children']::text[], '25 minutes', 'The parent sits with the child while they draw each helper and, together, decide what that person is good at helping with. Some children put the same adult in every spot; gently widen the list rather than correcting it. Hang the finished poster somewhere the child sees it, so the team stays visible after the session ends.', '[{"id": "f0", "type": "textarea", "label": "Someone who helps me when I am sad"}, {"id": "f1", "type": "textarea", "label": "Someone who helps me when I am scared"}, {"id": "f2", "type": "textarea", "label": "Someone who helps me when I am confused"}, {"id": "f3", "type": "textarea", "label": "Someone who helps me have fun"}, {"id": "f4", "type": "textarea", "label": "One more helper I want to add"}]'::jsonb, array['support network', 'children', 'family']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('brave-breathing-pinwheel-craft', 'Brave Breathing Pinwheel Craft', 'kids'::resource_kind, 'A child decorates a paper pinwheel and practices slow breaths that make it spin instead of blowing hard.', 'Use it to teach slow, paced breathing through a game a child wants to repeat.', array['Children']::text[], '20 minutes', 'The parent helps assemble the pinwheel and then practices alongside the child, since slow breathing is easier to copy than to be told. A fast, hard blow means the breath was too quick, which is useful feedback built right into the craft. Suggest the family use it together the next time anyone in the house is wound up, not only the child.', '[{"id": "f0", "type": "textarea", "label": "How fast the pinwheel spun when I blew too hard"}, {"id": "f1", "type": "textarea", "label": "How it spun when I blew slow and steady"}, {"id": "f2", "type": "textarea", "label": "A time I could use my breathing pinwheel"}, {"id": "f3", "type": "textarea", "label": "Who else in my family could use one"}]'::jsonb, array['breathing', 'children', 'regulation']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('kindness-detective-badge-craft', 'Kindness Detective Badge Craft', 'kids'::resource_kind, 'A child makes a detective badge and spends a week collecting evidence of kind things they notice or do.', 'Use it to build a child''s habit of noticing kindness in themselves and others.', array['Children']::text[], '20 minutes to make, one week to use', 'The parent helps make the badge and then checks in each evening for one piece of evidence, kind acts noticed or done, written or drawn. Evidence can be small; a shared crayon counts as much as a big gesture. Bring the collected evidence back to the next session and let the child choose their favorite one to talk about.', '[{"id": "f0", "type": "textarea", "label": "Kind thing I noticed someone else do"}, {"id": "f1", "type": "textarea", "label": "Kind thing I did"}, {"id": "f2", "type": "textarea", "label": "Kind thing done for me"}, {"id": "f3", "type": "textarea", "label": "My favorite piece of evidence from the week"}]'::jsonb, array['kindness', 'children', 'strengths']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('patience-jar-craft', 'Patience Jar Craft', 'kids'::resource_kind, 'A child decorates a jar and adds a bead each time they wait or try again without giving up.', 'Use it to give a child a visible, growing record of practicing patience.', array['Children']::text[], '20 minutes to make, ongoing to fill', 'The parent decides together with the child what counts, such as waiting a turn, trying a hard puzzle twice, or staying calm during a wait, and keeps the jar somewhere both can see. Celebrate the jar filling up rather than any single moment of impatience, and avoid using it to punish a hard day. Empty it and start again once it is full, and talk about what got easier.', '[{"id": "f0", "type": "textarea", "label": "Times this week I waited or tried again"}, {"id": "f1", "type": "textarea", "label": "What helped me do it"}, {"id": "f2", "type": "textarea", "label": "How the jar makes me feel when it fills up"}, {"id": "f3", "type": "textarea", "label": "What I want to celebrate when it is full"}]'::jsonb, array['patience', 'children', 'self-regulation']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('feelings-charades-relay', 'Feelings Charades Relay', 'game'::resource_kind, 'Teams race to act out feeling words silently while teammates guess, building a shared emotion vocabulary.', 'Use it to widen a group''s working vocabulary for naming feelings quickly.', array['Groups', 'Children', 'Teens']::text[], '20 minutes', 'Split into small teams and keep a running list of the words guessed correctly so the group ends with a visible vocabulary bank. Encourage acting the feeling in the body rather than a simple face, since bodies carry emotion clues too. Debrief by asking which feelings were hardest to act out and why, which is often the most useful five minutes of the game.', '[{"id": "f0", "type": "textarea", "label": "A feeling I acted out"}, {"id": "f1", "type": "textarea", "label": "A feeling that was hard to guess"}, {"id": "f2", "type": "textarea", "label": "One new feeling word I learned today"}, {"id": "f3", "type": "textarea", "label": "How I know that feeling in my own body"}]'::jsonb, array['emotion identification', 'play', 'group']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('active-listening-relay-game', 'Active Listening Relay Game', 'game'::resource_kind, 'One partner tells a short story and the other must retell it accurately before the group moves on.', 'Use it to make careless listening visible and reward the effort of listening well.', array['Groups', 'Couples', 'Teens']::text[], '20 minutes', 'Keep the stories short, thirty seconds or so, and ban note-taking, so the listener has to actually attend rather than transcribe. A retell that misses the point is worth pausing on gently; ask what pulled the listener''s attention away. Rotate roles so everyone practices both telling and listening, and debrief on what made a retell land well.', '[{"id": "f0", "type": "textarea", "label": "The story I told"}, {"id": "f1", "type": "textarea", "label": "How accurately my partner retold it"}, {"id": "f2", "type": "textarea", "label": "What I noticed pulled my attention away when I was listening"}, {"id": "f3", "type": "textarea", "label": "One thing I will do differently next time I listen"}]'::jsonb, array['listening', 'communication', 'play']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('perspective-taking-card-swap', 'Perspective-Taking Card Swap', 'game'::resource_kind, 'Players draw a scenario card and argue it from a viewpoint that is not their own, then swap and compare.', 'Use it to build the muscle of imagining a situation from someone else''s seat.', array['Groups', 'Teens', 'Couples']::text[], '25 minutes', 'Give each player a scenario and an assigned viewpoint that is deliberately not their natural one, and have them argue it honestly rather than as a caricature. Swap cards and argue the opposite side next round. Debrief on what was hard to imagine and what, if anything, shifted in how they see the original scenario.', '[{"id": "f0", "type": "textarea", "label": "The scenario and viewpoint I was given"}, {"id": "f1", "type": "textarea", "label": "The strongest point I could make from that viewpoint"}, {"id": "f2", "type": "textarea", "label": "What was hardest to imagine"}, {"id": "f3", "type": "textarea", "label": "What shifted for me after arguing the other side"}]'::jsonb, array['perspective-taking', 'empathy', 'play']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('empathy-map-charades', 'Empathy Map Charades', 'game'::resource_kind, 'Players act out a scenario while the group guesses what the person might be thinking, feeling and needing.', 'Use it to practice reading beyond a person''s visible behavior to what might be underneath it.', array['Groups', 'Teens']::text[], '25 minutes', 'Assign a short scenario, such as a friend who cancels plans last minute, and have one player act only the outward behavior. The group guesses possible thoughts, feelings and needs underneath before the actor reveals what they intended. Multiple guesses can all be plausible, which is itself the point: the same behavior can come from many different insides.', '[{"id": "f0", "type": "textarea", "label": "The scenario I acted or watched"}, {"id": "f1", "type": "textarea", "label": "What the group guessed the person might be thinking"}, {"id": "f2", "type": "textarea", "label": "What the group guessed the person might be feeling"}, {"id": "f3", "type": "textarea", "label": "What surprised me about the guesses"}]'::jsonb, array['empathy', 'perspective-taking', 'play']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('pattern-interrupt-freeze-game', 'Pattern Interrupt Freeze Game', 'game'::resource_kind, 'Players move and talk freely until a signal, then freeze and name what they were thinking at that instant.', 'Use it to practice catching a thought in real time rather than reconstructing it afterward.', array['Groups', 'Teens', 'Children']::text[], '15 minutes', 'Call freeze at unpredictable intervals and have each player say, out loud, the exact thought in their head at that moment, unedited. Some players will report nothing at first; that is normal and worth noting rather than pushing. Repeat several rounds and ask whether the thoughts caught got easier to notice as the game went on.', '[{"id": "f0", "type": "textarea", "label": "A thought I caught when we froze"}, {"id": "f1", "type": "textarea", "label": "Another one from a later round"}, {"id": "f2", "type": "textarea", "label": "Whether it got easier to notice my thoughts as we played"}, {"id": "f3", "type": "textarea", "label": "What I noticed about how fast my mind moves"}]'::jsonb, array['mindfulness', 'play', 'group']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('sensory-comfort-kit-planner', 'Sensory Comfort Kit Planner', 'worksheet'::resource_kind, 'Plans a physical kit of grounding objects a client keeps ready for moments of flooding or dissociation.', 'Use it to make grounding a kit that is ready, not a skill searched for mid-flood.', array['Adults', 'Teens']::text[], '20 minutes', 'Choose objects for at least three senses, something to hold, something to smell, something to look at, and keep the kit small enough to carry. Build it in session while the client is regulated, not in the middle of a hard moment. This stays a practical, present-focused tool; it does not ask the client to revisit what happened, only to have something steady on hand now.', '[{"id": "f0", "type": "textarea", "label": "Object to hold"}, {"id": "f1", "type": "textarea", "label": "Object to smell"}, {"id": "f2", "type": "textarea", "label": "Object to look at or read"}, {"id": "f3", "type": "textarea", "label": "Where this kit will live"}, {"id": "f4", "type": "textarea", "label": "A grounding phrase I want to pair with it"}]'::jsonb, array['PTSD and trauma', 'grounding', 'self-soothing']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('trauma-informed-boundary-script', 'Trauma-Informed Boundary Script', 'act'::resource_kind, 'Helps a client draft a short, values-based script for setting a limit with someone in their life now.', 'Use it to practice a present-day boundary as an act of choosing safety, not reliving the past.', array['Adults', 'Teens']::text[], '20 minutes', 'Keep the script about a specific, current situation, not about processing what happened before; this is about exercising choice today. Have the client name the value the boundary protects, and rehearse the script aloud in session before they use it. A short, plain sentence holds up better under pressure than a long explanation.', '[{"id": "f0", "type": "textarea", "label": "The situation where I want a boundary"}, {"id": "f1", "type": "textarea", "label": "The value this boundary protects"}, {"id": "f2", "type": "textarea", "label": "My script, in plain words"}, {"id": "f3", "type": "textarea", "label": "How I think the other person might respond"}, {"id": "f4", "type": "textarea", "label": "What I will do if they push back"}]'::jsonb, array['PTSD and trauma', 'boundaries', 'values']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('post-session-regulation-card', 'Post-Session Regulation Card', 'dbt'::resource_kind, 'A short skills card a client uses to settle their body in the minutes right after a hard session.', 'Use it to help a client leave the room regulated enough to drive, work or parent.', array['Adults', 'Teens']::text[], 'Five minutes', 'Build it together and keep it to skills the client can do alone in a car or a waiting room: paced breathing, a grounding object, a short walk. Use it after any session that touched heavy material, not only after something dramatic happened. Check in the following week on whether it actually got used and adjust it if not.', '[{"id": "f0", "type": "textarea", "label": "A breathing pace I can use in the car"}, {"id": "f1", "type": "textarea", "label": "A grounding object I keep with me"}, {"id": "f2", "type": "textarea", "label": "A short activity for the first hour after session"}, {"id": "f3", "type": "textarea", "label": "Someone I can text if I need extra support"}]'::jsonb, array['PTSD and trauma', 'grounding', 'regulation']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('safe-person-reach-out-practice', 'Safe Person Reach-Out Practice', 'couples'::resource_kind, 'Practices a client asking a partner for support in a hard moment, and the partner offering it without fixing.', 'Use it to build a rehearsed way to ask for and give support without either partner freezing.', array['Couples']::text[], '25 minutes', 'Have the client name exactly what kind of support helps, staying present, a hand held, quiet company, and have the partner practice offering it without asking for the story behind it. Rehearse the actual words each will use in the moment. The goal is a reliable, low-pressure routine both partners can lean on, not a conversation about what happened.', '[{"id": "f0", "type": "textarea", "label": "What kind of support actually helps me"}, {"id": "f1", "type": "textarea", "label": "The words I will use to ask for it"}, {"id": "f2", "type": "textarea", "label": "What my partner will say or do in response"}, {"id": "f3", "type": "textarea", "label": "What my partner should avoid doing in that moment"}]'::jsonb, array['PTSD and trauma', 'support', 'couples']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('felt-safety-check-in-sheet', 'Felt Safety Check-In Sheet', 'cbt'::resource_kind, 'A quick rating of how safe a client''s body feels right now, tracked across the week to spot patterns.', 'Use it to track felt safety over time and notice what reliably moves the number.', array['Adults', 'Teens']::text[], 'Five minutes daily for one week', 'Ask for a plain number, zero to ten, for how safe the body feels in this moment, logged a few times a day without explanation required. Look together at the week''s pattern rather than any single low reading. This tracks present-moment safety only; it is not an invitation to describe the original event.', '[{"id": "f0", "type": "textarea", "label": "Morning felt-safety number, zero to ten"}, {"id": "f1", "type": "textarea", "label": "Afternoon felt-safety number"}, {"id": "f2", "type": "textarea", "label": "Evening felt-safety number"}, {"id": "f3", "type": "textarea", "label": "What seemed to move the number up"}, {"id": "f4", "type": "textarea", "label": "What seemed to move the number down"}]'::jsonb, array['PTSD and trauma', 'monitoring', 'regulation']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('anxiety-prediction-scorecard', 'Anxiety Prediction Scorecard', 'cbt'::resource_kind, 'Logs a client''s predicted worst outcome against what actually happened, scored over a week.', 'Use it to build evidence, in the client''s own data, that predictions run worse than reality.', array['Adults', 'Teens']::text[], 'One week', 'Have the client write the specific prediction and a confidence rating before the event, then the actual outcome afterward, without editing the earlier entry. Tally the week''s accuracy rate together rather than letting a single lucky guess stand for the pattern. Most clients are startled by how the total lands; let the total speak instead of pointing it out.', '[{"id": "f0", "type": "textarea", "label": "Situation I am worried about"}, {"id": "f1", "type": "textarea", "label": "My predicted outcome"}, {"id": "f2", "type": "textarea", "label": "My confidence in that prediction, zero to ten"}, {"id": "f3", "type": "textarea", "label": "What actually happened"}, {"id": "f4", "type": "textarea", "label": "How accurate my prediction turned out to be"}]'::jsonb, array['anxiety', 'prediction', 'evidence']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('worry-backpack-unpacking-practice', 'Worry Backpack Unpacking Practice', 'act'::resource_kind, 'A metaphor exercise for noticing how much a client is carrying versus how much is actually happening now.', 'Use it to build a physical sense of setting worry down rather than carrying it everywhere.', array['Adults', 'Teens']::text[], '15 minutes', 'Ask the client to literally hold a heavy bag while describing their week, then set it down and describe the same week again. The exercise makes the weight of anticipatory worry tangible rather than abstract. Practice a short, repeatable gesture, like setting a hand down flat, that the client can use outside session to signal setting the backpack down for now.', '[{"id": "f0", "type": "textarea", "label": "What is in my worry backpack this week"}, {"id": "f1", "type": "textarea", "label": "How the week sounded while holding the bag"}, {"id": "f2", "type": "textarea", "label": "How the week sounded after setting it down"}, {"id": "f3", "type": "textarea", "label": "My gesture for setting the backpack down"}]'::jsonb, array['anxiety', 'acceptance', 'mindfulness']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('anxiety-interrupt-and-redirect-card', 'Anxiety Interrupt and Redirect Card', 'dbt'::resource_kind, 'A short DBT skills card pairing a quick interrupt action with a redirect toward something values-driven.', 'Use it to give a client a two-step move for the moment anxiety spikes mid-task.', array['Adults', 'Teens']::text[], '15 minutes', 'Pick one fast interrupt, cold water, a hard exhale, standing up, and pair it with one specific redirect back to the task at hand rather than a full escape. Practice the pairing in session until it feels automatic rather than something to remember under pressure. Track over the week whether the pair actually gets used and adjust either half if it does not.', '[{"id": "f0", "type": "textarea", "label": "My interrupt action"}, {"id": "f1", "type": "textarea", "label": "My redirect action"}, {"id": "f2", "type": "textarea", "label": "A moment this week I tried the pair"}, {"id": "f3", "type": "textarea", "label": "How it went"}]'::jsonb, array['anxiety', 'distress tolerance', 'skills']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('worry-monster-feeding-chart', 'Worry Monster Feeding Chart', 'kids'::resource_kind, 'A child decides which worries to feed with attention and which to let their Worry Monster go hungry on.', 'Use it to give a child a playful, concrete way to choose which worries get their attention.', array['Children']::text[], '20 minutes', 'The parent helps the child draw or name their Worry Monster and sort recent worries into feed now, in the worry box, or throw away. Keep the sorting language playful and let the child make the final call on each worry rather than the parent deciding for them. Revisit the chart weekly and notice which worries the child stops feeding on their own.', '[{"id": "f0", "type": "textarea", "label": "A worry I am feeding right now"}, {"id": "f1", "type": "textarea", "label": "A worry going in my worry box for later"}, {"id": "f2", "type": "textarea", "label": "A worry I am throwing away"}, {"id": "f3", "type": "textarea", "label": "What my Worry Monster looks like"}]'::jsonb, array['anxiety', 'children', 'externalizing']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('anxiety-facts-relay-game', 'Anxiety Facts Relay Game', 'game'::resource_kind, 'Teams race to sort true statements about how anxiety works from common myths, then discuss the misses.', 'Use it to correct unhelpful beliefs about anxiety through a low-stakes group format.', array['Groups', 'Teens']::text[], '20 minutes', 'Prepare a set of true and myth cards about how anxiety behaves in the body and mind, and have teams sort them quickly before checking answers together. The misses are the most useful part; slow down there rather than moving on fast. Close by asking what surprised the group most and how that changes how they think about their own anxiety.', '[{"id": "f0", "type": "textarea", "label": "A myth I believed before this game"}, {"id": "f1", "type": "textarea", "label": "A fact that surprised me"}, {"id": "f2", "type": "textarea", "label": "How this changes what I do when anxiety shows up"}]'::jsonb, array['anxiety', 'psychoeducation', 'play']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('micro-momentum-activity-log', 'Micro-Momentum Activity Log', 'cbt'::resource_kind, 'Logs the smallest possible version of an activity a client can complete on a low-energy day.', 'Use it to keep behavioral activation going on the days full activities feel impossible.', array['Adults', 'Teens']::text[], 'One week', 'Scale each planned activity down to a version so small it feels almost silly, one page instead of a chapter, one dish instead of the whole kitchen. Log mood before and after even the tiny version. The point is proving to the client''s own nervous system that action is still possible, not producing an impressive amount of output.', '[{"id": "f0", "type": "textarea", "label": "The activity I scaled down"}, {"id": "f1", "type": "textarea", "label": "The tiny version I actually did"}, {"id": "f2", "type": "textarea", "label": "Mood before, zero to ten"}, {"id": "f3", "type": "textarea", "label": "Mood after, zero to ten"}, {"id": "f4", "type": "textarea", "label": "What I noticed"}]'::jsonb, array['depression', 'behavioral activation', 'monitoring']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('values-anchor-for-low-energy-days', 'Values Anchor for Low-Energy Days', 'act'::resource_kind, 'Picks one small values-aligned action a client can do even on the hardest, lowest-energy days.', 'Use it to keep one thread of meaning intact when most of the day''s plans fall away.', array['Adults', 'Teens']::text[], '15 minutes', 'Ask what matters to the client even when energy is at its lowest, then find one action so small it survives a bad day, texting one person, watering one plant, stepping outside for a minute. Hold this separate from the client''s full activity plan as a floor, not a replacement. Review which low-energy actions actually got used and keep only those.', '[{"id": "f0", "type": "textarea", "label": "What still matters to me even on a hard day"}, {"id": "f1", "type": "textarea", "label": "The smallest action that honors it"}, {"id": "f2", "type": "textarea", "label": "A day this week I used my low-energy action"}, {"id": "f3", "type": "textarea", "label": "How it felt to do even that much"}]'::jsonb, array['depression', 'values', 'behavioral activation']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('withdrawal-warning-signs-worksheet', 'Withdrawal Warning Signs Worksheet', 'worksheet'::resource_kind, 'Catalogs a client''s early signs of pulling away from people and routines before a full withdrawal sets in.', 'Use it to catch withdrawal early, while a small nudge back still works.', array['Adults', 'Teens']::text[], '20 minutes', 'Ask the client to think back to the start of a past low period and name what changed first, canceled plans, unanswered texts, skipped meals, rather than what changed last. Agree together on one early sign to watch for and one small counter-action tied to it. Revisit the list after any low stretch and add whatever the client notices in hindsight.', '[{"id": "f0", "type": "textarea", "label": "The first sign I usually notice"}, {"id": "f1", "type": "textarea", "label": "A second early sign"}, {"id": "f2", "type": "textarea", "label": "One small counter-action for the first sign"}, {"id": "f3", "type": "textarea", "label": "Who I want to know to check on me if these signs show up"}]'::jsonb, array['depression', 'early warning signs', 'monitoring']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('opposite-action-for-withdrawal-card', 'Opposite Action for Withdrawal Card', 'dbt'::resource_kind, 'A DBT skills card for acting opposite to the urge to withdraw, in small, planned amounts.', 'Use it to practice moving toward contact even when everything points toward pulling away.', array['Adults', 'Teens']::text[], '15 minutes', 'Name the urge honestly, cancel the plan, do not answer, stay in bed, and pick one small opposite action that still fits inside what the client can manage today. Full opposite action is not the goal on a first try; a five-minute version counts. Log which opposite actions actually got tried and how mood moved afterward.', '[{"id": "f0", "type": "textarea", "label": "The urge to withdraw, named plainly"}, {"id": "f1", "type": "textarea", "label": "The opposite action, scaled to what I can manage"}, {"id": "f2", "type": "textarea", "label": "What I actually did"}, {"id": "f3", "type": "textarea", "label": "How I felt afterward"}]'::jsonb, array['depression', 'opposite action', 'behavioral activation']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('supporting-low-mood-without-fixing-script', 'Supporting Low Mood Without Fixing Script', 'couples'::resource_kind, 'A short script for a partner to offer presence during a low-mood stretch without trying to fix it.', 'Use it to give both partners a shared plan for the hard weeks, not just the good ones.', array['Couples']::text[], '20 minutes', 'Ask the client with low mood what actually helps, being asked how they are, being left alone, having a task taken off their plate, and have the partner practice offering exactly that instead of guessing. Name together what unhelpful support tends to look like for this couple specifically. Revisit the script after a real low-mood week and adjust it based on what worked.', '[{"id": "f0", "type": "textarea", "label": "What actually helps me on a low-mood day"}, {"id": "f1", "type": "textarea", "label": "What does not help, even if well-meant"}, {"id": "f2", "type": "textarea", "label": "What my partner will say or do"}, {"id": "f3", "type": "textarea", "label": "One task my partner can take off my plate on hard days"}]'::jsonb, array['depression', 'support', 'couples']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('energy-mapping-by-hour-worksheet', 'Energy Mapping by Hour Worksheet', 'worksheet'::resource_kind, 'Maps a client''s actual focus and energy levels across the day to match tasks to the right window.', 'Use it to schedule demanding tasks into the hours where focus is actually available.', array['Adults', 'Teens']::text[], 'One week', 'Have the client rate focus and energy every couple of hours for several days, without trying to fix the pattern while logging it. Most clients are scheduling their hardest tasks into their worst hours out of habit, not choice. Use the finished map to move one demanding task into a better window and see what changes.', '[{"id": "f0", "type": "textarea", "label": "8 to 10 a.m. focus level"}, {"id": "f1", "type": "textarea", "label": "10 a.m. to noon focus level"}, {"id": "f2", "type": "textarea", "label": "Afternoon focus level"}, {"id": "f3", "type": "textarea", "label": "Evening focus level"}, {"id": "f4", "type": "textarea", "label": "One task I want to move to a better window"}]'::jsonb, array['ADHD', 'executive function', 'monitoring']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('external-memory-system-audit', 'External Memory System Audit', 'cbt'::resource_kind, 'Reviews where a client currently tries to hold information in their head versus writing it down.', 'Use it to shift reliance from working memory onto a system the client trusts.', array['Adults', 'Teens']::text[], '20 minutes', 'List the places information currently lives, in the head, on scraps of paper, in three different apps, and be honest about what actually gets checked. A system only works if the client will actually open it, so favor the boring, low-friction option over the elegant one. Agree on a single place for one category of information and test it for a week before adding more.', '[{"id": "f0", "type": "textarea", "label": "What I currently try to remember without writing it down"}, {"id": "f1", "type": "textarea", "label": "Where information currently lives (list every place)"}, {"id": "f2", "type": "textarea", "label": "Which of these I actually check"}, {"id": "f3", "type": "textarea", "label": "One category I will move to a single trusted place"}]'::jsonb, array['ADHD', 'executive function', 'systems']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('body-double-buddy-craft', 'Body Double Buddy Craft', 'kids'::resource_kind, 'A child makes a small figure or drawing of a body double buddy who sits with them during homework.', 'Use it to give a child a comforting visual cue for working alongside someone, even in imagination.', array['Children']::text[], '20 minutes', 'The parent helps the child make a small figure, drawing or cutout and decide what the buddy is good at, keeping me company, reminding me to look back at my paper. Place the buddy at the workspace during homework or chores as a visual anchor. Pair it with real body doubling from a parent or sibling when possible, since the craft supports the habit rather than replacing another person.', '[{"id": "f0", "type": "textarea", "label": "What my body double buddy looks like"}, {"id": "f1", "type": "textarea", "label": "What my buddy is good at helping with"}, {"id": "f2", "type": "textarea", "label": "Where my buddy sits when I work"}, {"id": "f3", "type": "textarea", "label": "A time this week my buddy helped me stay on task"}]'::jsonb, array['ADHD', 'children', 'task initiation']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('beat-the-clutter-timer-game', 'Beat the Clutter Timer Game', 'game'::resource_kind, 'A timed, playful race to clear one small space before a timer runs out, repeated in short bursts.', 'Use it to make a tedious task feel like a game with a clear, short endpoint.', array['Children', 'Teens', 'Adults']::text[], '10 minutes', 'Set a short timer, five or ten minutes, for one specific small area rather than an entire room, and celebrate what got done when time is up rather than what did not. Some clients do best racing against their own last time; others do better with a partner. Repeat in short bursts with breaks rather than one long push.', '[{"id": "f0", "type": "textarea", "label": "The space I cleared"}, {"id": "f1", "type": "textarea", "label": "My time"}, {"id": "f2", "type": "textarea", "label": "What I got done before the timer ended"}, {"id": "f3", "type": "textarea", "label": "Whether I want to race myself or a partner next time"}]'::jsonb, array['ADHD', 'task initiation', 'play']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('present-task-return-practice', 'Present-Task Return Practice', 'act'::resource_kind, 'Practices noticing when attention has drifted and gently returning to the task at hand, without self-blame.', 'Use it to build the skill of returning to task as a repeated practice, not a one-time fix.', array['Adults', 'Teens']::text[], '15 minutes', 'Have the client work on a real task while noting each time attention wanders and simply marking a tally rather than judging the drift. The tally is not a score to minimize; a high count just means more practice returning. Emphasize the return itself as the skill being built, since attention will keep wandering no matter how this goes.', '[{"id": "f0", "type": "textarea", "label": "The task I practiced on"}, {"id": "f1", "type": "textarea", "label": "How many times I noticed my attention had drifted"}, {"id": "f2", "type": "textarea", "label": "What usually pulled my attention away"}, {"id": "f3", "type": "textarea", "label": "How it felt to return without judging myself for drifting"}]'::jsonb, array['ADHD', 'mindfulness', 'attention']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('urge-curve-tracking-sheet', 'Urge Curve Tracking Sheet', 'cbt'::resource_kind, 'Logs how long an urge to use actually lasts, rated every few minutes, to test its predicted duration.', 'Use it to build evidence that urges pass in minutes rather than the hours they can feel like.', array['Adults', 'Teens']::text[], 'One week', 'Have the client rate the urge every five minutes during an episode rather than only at the start and end, since the shape of the curve is the useful part. Most urges peak and fall within fifteen to twenty minutes if nothing feeds them. Compare the client''s prediction of how long it would last against the actual tracked curve.', '[{"id": "f0", "type": "textarea", "label": "What triggered the urge"}, {"id": "f1", "type": "textarea", "label": "Urge intensity at minute 0"}, {"id": "f2", "type": "textarea", "label": "Urge intensity at minute 5"}, {"id": "f3", "type": "textarea", "label": "Urge intensity at minute 10"}, {"id": "f4", "type": "textarea", "label": "Urge intensity at minute 20"}, {"id": "f5", "type": "textarea", "label": "How long I predicted it would last versus how long it did"}]'::jsonb, array['addiction', 'urges', 'monitoring']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('values-beyond-the-next-use-practice', 'Values Beyond the Next Use Practice', 'act'::resource_kind, 'Connects a client''s reasons for changing their substance use to concrete values rather than rules alone.', 'Use it to anchor change work in what the client actually wants their life to hold.', array['Adults', 'Teens']::text[], '20 minutes', 'Ask what substance use has cost the client in terms of what actually matters to them, not just in problems it has caused. Build a short values statement the client can return to when willpower alone is not enough. This sits alongside a change plan rather than replacing the practical steps a client also needs.', '[{"id": "f0", "type": "textarea", "label": "What matters most to me that substance use has gotten in the way of"}, {"id": "f1", "type": "textarea", "label": "What I want more of in my life"}, {"id": "f2", "type": "textarea", "label": "My values statement, in my own words"}, {"id": "f3", "type": "textarea", "label": "Where I will keep this statement so I see it"}]'::jsonb, array['addiction', 'values', 'motivation']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('riding-the-urge-skills-card', 'Riding the Urge Skills Card', 'dbt'::resource_kind, 'A short DBT card for tolerating an urge to use without acting on it or fighting it away.', 'Use it to practice staying present with an urge long enough for it to pass on its own.', array['Adults', 'Teens']::text[], '15 minutes', 'Teach the client to notice the urge without immediately either giving in or white-knuckling against it, describing it out loud instead: where it is, what it feels like, how it changes. Pair it with one grounding action the client can do while riding the urge out. Practice with a mild version of the urge in session before relying on it during a real high-risk moment.', '[{"id": "f0", "type": "textarea", "label": "Where I feel the urge in my body"}, {"id": "f1", "type": "textarea", "label": "How the urge changes as I describe it"}, {"id": "f2", "type": "textarea", "label": "The grounding action I paired with it"}, {"id": "f3", "type": "textarea", "label": "A moment this week I rode an urge out"}]'::jsonb, array['addiction', 'urges', 'distress tolerance']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('substance-free-identity-worksheet', 'Substance-Free Identity Worksheet', 'worksheet'::resource_kind, 'Explores who a client wants to be day to day, separate from a substance-focused daily rhythm.', 'Use it to build a picture of a life worth having, not just a list of things to avoid.', array['Adults', 'Teens']::text[], '25 minutes', 'Ask what a typical day looks like now around substance use, and then ask the client to describe a typical day in the life they are building instead, in as much concrete detail as they can manage. Avoid making this a punishment list of what to give up; keep it forward-looking. Return to the description regularly as a north star rather than a one-time exercise.', '[{"id": "f0", "type": "textarea", "label": "A typical day now, around substance use"}, {"id": "f1", "type": "textarea", "label": "A typical day in the life I am building"}, {"id": "f2", "type": "textarea", "label": "One thing from that description I can start this week"}, {"id": "f3", "type": "textarea", "label": "What this life gives me that using does not"}]'::jsonb, array['addiction', 'identity', 'motivation']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('support-versus-enabling-map', 'Support Versus Enabling Map', 'couples'::resource_kind, 'Helps a couple map the line between supporting recovery and covering for continued substance use.', 'Use it to give both partners a shared, specific picture of what support looks like here.', array['Couples']::text[], '25 minutes', 'Have each partner list, separately at first, what they consider supportive versus what crosses into covering up or managing the other''s substance use, then compare lists together. Disagreement here is common and worth slowing down on rather than resolving quickly. Agree on two or three concrete lines the non-using partner will hold, and revisit the map as recovery progresses.', '[{"id": "f0", "type": "textarea", "label": "What support looks like to me"}, {"id": "f1", "type": "textarea", "label": "What crosses the line into covering up or managing, to me"}, {"id": "f2", "type": "textarea", "label": "Where our two lists disagree"}, {"id": "f3", "type": "textarea", "label": "Two lines we agree to hold as a couple"}]'::jsonb, array['addiction', 'couples', 'boundaries']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('anger-escalation-ladder-worksheet', 'Anger Escalation Ladder Worksheet', 'worksheet'::resource_kind, 'Maps a client''s own anger from a one to a ten, naming what each rung actually looks and feels like.', 'Use it to build a personal early-warning system before anger reaches the top of the ladder.', array['Adults', 'Teens']::text[], '20 minutes', 'Ask for the client''s own words at each rung rather than generic descriptions, since annoyed and furious feel different in every body. Mark the rung where a cooling skill still works versus the rung past which it usually does not. Use the ladder together to plan an exit or pause before the client reaches their point of no return.', '[{"id": "f0", "type": "textarea", "label": "What a level 2 looks like for me"}, {"id": "f1", "type": "textarea", "label": "What a level 5 looks like for me"}, {"id": "f2", "type": "textarea", "label": "What a level 8 looks like for me"}, {"id": "f3", "type": "textarea", "label": "The rung where I need to leave the situation"}, {"id": "f4", "type": "textarea", "label": "A skill that still works below that rung"}]'::jsonb, array['anger management', 'self-monitoring', 'regulation']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('fair-fight-rules-reality-check', 'Fair Fight Rules Reality Check', 'cbt'::resource_kind, 'Compares a client''s actual conflict behavior against a short set of self-chosen ground rules for arguing fair.', 'Use it to catch the gap between the rules a client believes in and what happens under pressure.', array['Adults', 'Teens']::text[], '20 minutes', 'Have the client write their own rules for fighting fair before reviewing a recent conflict against them, so the standard is theirs, not imposed. Be specific about which rule broke first and what was happening in the client''s body right before it did. Use the pattern to plan one rule to protect first next time, rather than trying to fix all of them at once.', '[{"id": "f0", "type": "textarea", "label": "My rules for fighting fair, in my own words"}, {"id": "f1", "type": "textarea", "label": "A recent conflict, briefly"}, {"id": "f2", "type": "textarea", "label": "Which rule broke first"}, {"id": "f3", "type": "textarea", "label": "What was happening in my body right before it broke"}, {"id": "f4", "type": "textarea", "label": "The one rule I will protect first next time"}]'::jsonb, array['anger management', 'conflict', 'self-monitoring']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('slow-burn-cooling-card', 'Slow Burn Cooling Card', 'dbt'::resource_kind, 'A skills card for anger that builds slowly over a day rather than spiking suddenly.', 'Use it to catch and cool a slow-building irritation before it reaches a flashpoint.', array['Adults', 'Teens']::text[], '15 minutes', 'Ask the client to notice the small irritations that stack across a day rather than waiting for the final trigger that gets blamed. List one cooling action for the middle of the day and one for the end, since a slow burn needs interruption earlier than a sudden spike does. Track which point in the day the stacking usually starts.', '[{"id": "f0", "type": "textarea", "label": "What tends to stack up across my day"}, {"id": "f1", "type": "textarea", "label": "A cooling action for midday"}, {"id": "f2", "type": "textarea", "label": "A cooling action for the end of the day"}, {"id": "f3", "type": "textarea", "label": "The point in the day I usually notice the stack getting heavy"}]'::jsonb, array['anger management', 'distress tolerance', 'regulation']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('anger-weather-forecast-craft', 'Anger Weather Forecast Craft', 'kids'::resource_kind, 'A child makes a weather forecast board that shows their anger as sunny, cloudy, stormy or clear again.', 'Use it to give a child and parent a shared, simple language for talking about building anger.', array['Children']::text[], '20 minutes', 'The parent helps build the forecast board and agrees with the child on what each weather symbol means for their own anger, sunny for calm, stormy for a meltdown. Practice checking the day''s forecast together at a few set times rather than only during a blow-up. The goal is a shared word the family can use in the moment, not a permanent record.', '[{"id": "f0", "type": "textarea", "label": "What sunny anger looks like for me"}, {"id": "f1", "type": "textarea", "label": "What cloudy anger looks like for me"}, {"id": "f2", "type": "textarea", "label": "What stormy anger looks like for me"}, {"id": "f3", "type": "textarea", "label": "One thing that helps the weather clear"}]'::jsonb, array['anger management', 'children', 'regulation']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('cool-head-trivia-relay', 'Cool Head Trivia Relay', 'game'::resource_kind, 'Teams answer quick trivia questions about what happens in the body during anger, racing for points.', 'Use it to teach the biology of anger in a format a group actually wants to play.', array['Groups', 'Teens']::text[], '20 minutes', 'Prepare short trivia questions about what heart rate, breathing and muscles do during anger, and let teams race to answer before a timer runs out. Correct wrong answers with the real explanation rather than just the right choice, since the explanation is what sticks. Close by asking how knowing the biology changes what the group tries the next time anger builds.', '[{"id": "f0", "type": "textarea", "label": "A fact about anger and the body I learned today"}, {"id": "f1", "type": "textarea", "label": "Something I got wrong that surprised me"}, {"id": "f2", "type": "textarea", "label": "How this changes what I will try next time I am angry"}]'::jsonb, array['anger management', 'psychoeducation', 'play']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('certainty-demand-audit', 'Certainty Demand Audit', 'cbt'::resource_kind, 'Lists the specific certainties a client''s mind keeps demanding before it will let a worry rest.', 'Use it to make the impossible standard behind compulsions visible and questionable.', array['Adults', 'Teens']::text[], '20 minutes', 'Ask the client what percentage of certainty would actually be enough to stop checking or seeking reassurance, and notice when the honest answer is one hundred. Point out, without arguing, that no one operates at that standard anywhere else in life. Use the gap to open a conversation about tolerating a lower, ordinary level of certainty.', '[{"id": "f0", "type": "textarea", "label": "The worry my mind wants certainty about"}, {"id": "f1", "type": "textarea", "label": "What percentage certain would be enough to stop"}, {"id": "f2", "type": "textarea", "label": "Where else in life I already tolerate less certainty than that"}, {"id": "f3", "type": "textarea", "label": "What tolerating ordinary certainty here would look like"}]'::jsonb, array['OCD', 'uncertainty', 'cognitive restructuring']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('sitting-with-the-itch-practice', 'Sitting With the Itch Practice', 'act'::resource_kind, 'Practices noticing the urge to complete a compulsion as a passing sensation rather than an instruction.', 'Use it to build tolerance for the urge itself, separate from acting on it.', array['Adults', 'Teens']::text[], '15 minutes', 'Ask the client to describe the urge to complete a compulsion the way they would describe an itch, where it is, how strong, whether it changes if they do not scratch it. Track how the urge moves over a few minutes without engaging the compulsion. This builds a felt sense that the urge itself is bearable, not just an intellectual fact.', '[{"id": "f0", "type": "textarea", "label": "The urge and what it wants me to do"}, {"id": "f1", "type": "textarea", "label": "Where I notice it in my body"}, {"id": "f2", "type": "textarea", "label": "How it changed over the next five minutes"}, {"id": "f3", "type": "textarea", "label": "What I did instead of the compulsion"}]'::jsonb, array['OCD', 'willingness', 'urges']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('response-delay-ladder-card', 'Response Delay Ladder Card', 'dbt'::resource_kind, 'A skills card for building delay time between an obsessive thought and a compulsive response, in small steps.', 'Use it to grow the gap between urge and response gradually rather than all at once.', array['Adults', 'Teens']::text[], '20 minutes', 'Start from whatever delay is currently realistic, even thirty seconds, and add time only once the current step feels manageable. Pair the delay with a specific skill to use during the wait, breathing, describing the urge, rather than leaving the client to just wait it out unaided. Celebrate the delay itself, whether or not the compulsion eventually happens.', '[{"id": "f0", "type": "textarea", "label": "The compulsion I am working on delaying"}, {"id": "f1", "type": "textarea", "label": "My current delay time"}, {"id": "f2", "type": "textarea", "label": "A skill I will use during the delay"}, {"id": "f3", "type": "textarea", "label": "My next delay goal"}]'::jsonb, array['OCD', 'response delay', 'skills']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('uncertainty-monster-feeding-chart', 'Uncertainty Monster Feeding Chart', 'kids'::resource_kind, 'A child decides which what-ifs to feed with checking and which to let their Uncertainty Monster go hungry on.', 'Use it to give a child a playful way to notice and resist feeding compulsive checking.', array['Children']::text[], '20 minutes', 'The parent helps the child name and draw their Uncertainty Monster and sort recent what-if worries into feed or starve, with the child making the final call each time. Praise not feeding the monster as the brave choice, even when checking would have felt easier. If a child discloses anything during this activity that raises safety concerns, stop the activity and follow your mandated reporting duties.', '[{"id": "f0", "type": "textarea", "label": "A what-if I am not feeding today"}, {"id": "f1", "type": "textarea", "label": "How it felt to not check"}, {"id": "f2", "type": "textarea", "label": "What my Uncertainty Monster looks like"}, {"id": "f3", "type": "textarea", "label": "One brave choice I made this week"}]'::jsonb, array['OCD', 'children', 'externalizing']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('mental-ritual-spotting-worksheet', 'Mental Ritual Spotting Worksheet', 'worksheet'::resource_kind, 'Helps a client identify rituals that happen entirely in their head, which are easy to miss on a checklist.', 'Use it to bring invisible mental compulsions into view alongside the visible ones.', array['Adults', 'Teens']::text[], '20 minutes', 'Ask directly about counting, silent praying, mental reviewing or replaying, and repeating phrases internally, since these rarely get reported unless asked about by name. List what each mental ritual is meant to prevent or undo. Once spotted, mental rituals can be worked with the same delay and response-prevention approach as visible ones.', '[{"id": "f0", "type": "textarea", "label": "A mental ritual I do (counting, reviewing, repeating words)"}, {"id": "f1", "type": "textarea", "label": "What I believe it prevents or undoes"}, {"id": "f2", "type": "textarea", "label": "How often it happens on a typical day"}, {"id": "f3", "type": "textarea", "label": "One I am willing to start delaying"}]'::jsonb, array['OCD', 'mental compulsions', 'self-monitoring']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('panic-sensation-inventory', 'Panic Sensation Inventory', 'cbt'::resource_kind, 'Catalogs exactly which body sensations show up during a client''s panic attacks and what each one is mistaken for.', 'Use it to separate the sensation itself from the alarming meaning attached to it.', array['Adults', 'Teens']::text[], '20 minutes', 'List each sensation, racing heart, tight chest, dizziness, specifically, then write the alarming interpretation next to it and a more accurate, harmless explanation beside that. Bring in a medical clearance already on file rather than reopening that question here. Use the finished inventory as a reference the client can reread when a sensation starts to spiral.', '[{"id": "f0", "type": "textarea", "label": "Sensation 1 and the alarming thought attached to it"}, {"id": "f1", "type": "textarea", "label": "A more accurate explanation for sensation 1"}, {"id": "f2", "type": "textarea", "label": "Sensation 2 and its alarming thought"}, {"id": "f3", "type": "textarea", "label": "A more accurate explanation for sensation 2"}, {"id": "f4", "type": "textarea", "label": "What I want to remember when these sensations start"}]'::jsonb, array['panic attacks', 'psychoeducation', 'interoception']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('panic-wave-riding-card', 'Panic Wave Riding Card', 'dbt'::resource_kind, 'A skills card for staying present through a panic attack''s rise and fall instead of fighting it.', 'Use it to practice riding out the physical wave rather than racing to escape it.', array['Adults', 'Teens']::text[], '15 minutes', 'Walk through the shape of a wave with the client, a rise, a peak, a fall, and pick one anchor phrase or physical anchor to hold through all three parts rather than only at the start. Practice narrating the wave out loud in session using a mild example first. Track afterward how long an actual episode lasted against how long it felt like it lasted.', '[{"id": "f0", "type": "textarea", "label": "My anchor phrase or physical anchor"}, {"id": "f1", "type": "textarea", "label": "What the rise usually feels like"}, {"id": "f2", "type": "textarea", "label": "What the peak usually feels like"}, {"id": "f3", "type": "textarea", "label": "How long an episode actually lasted versus how long it felt"}]'::jsonb, array['panic attacks', 'distress tolerance', 'grounding']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('life-beyond-the-next-attack-practice', 'Life Beyond the Next Attack Practice', 'act'::resource_kind, 'Identifies activities a client has been avoiding out of fear of a panic attack happening there.', 'Use it to reclaim activity and place from the fear of where an attack might strike.', array['Adults', 'Teens']::text[], '20 minutes', 'List places and activities currently avoided because of where a past attack happened or might happen, and rank them from least to most avoided. Choose one low-avoidance item to reintroduce this week with a concrete plan for support if an attack occurs. The goal is a life that is not shaped around avoiding panic, not the elimination of panic itself.', '[{"id": "f0", "type": "textarea", "label": "A place or activity I avoid because of panic"}, {"id": "f1", "type": "textarea", "label": "Another one"}, {"id": "f2", "type": "textarea", "label": "Ranked from easiest to hardest to try again"}, {"id": "f3", "type": "textarea", "label": "My plan for the easiest one this week"}]'::jsonb, array['panic attacks', 'avoidance', 'values']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('supporting-someone-mid-panic-script', 'Supporting Someone Mid-Panic Script', 'couples'::resource_kind, 'A short, rehearsed script for a partner to use while their partner is having a panic attack.', 'Use it to replace guessing with a calm, practiced response in the moment.', array['Couples']::text[], '20 minutes', 'Ask the client having panic attacks what actually helps versus what makes things worse, being talked through breathing, being left quiet, being reminded this will pass, and have the partner rehearse exactly those words. Agree on what the partner should avoid, such as rushing to call for help unless there is a real medical concern. Revisit the script after it has been used for real and refine it.', '[{"id": "f0", "type": "textarea", "label": "What helps me during a panic attack"}, {"id": "f1", "type": "textarea", "label": "What makes it worse, even if well-meant"}, {"id": "f2", "type": "textarea", "label": "Exact words my partner can say"}, {"id": "f3", "type": "textarea", "label": "What my partner should avoid doing"}]'::jsonb, array['panic attacks', 'support', 'couples']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('brave-belly-breathing-chart', 'Brave Belly Breathing Chart', 'kids'::resource_kind, 'A child practices slow belly breathing using a chart that tracks the rise and fall of a stuffed animal on their tummy.', 'Use it to teach a calming skill a scared or panicky child can use anywhere.', array['Children']::text[], '15 minutes', 'The parent lies down with the child and practices together, placing a small stuffed animal on the belly and watching it rise and fall slowly. Count breaths together on the chart rather than asking the child to count alone at first. Practice when calm so the skill is familiar before it is needed during a scared moment.', '[{"id": "f0", "type": "textarea", "label": "How high the stuffed animal rose on my best breath"}, {"id": "f1", "type": "textarea", "label": "How many slow breaths I practiced today"}, {"id": "f2", "type": "textarea", "label": "A time I felt scared and could try this"}, {"id": "f3", "type": "textarea", "label": "Who I practiced with"}]'::jsonb, array['panic attacks', 'children', 'breathing']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('connection-before-correction-chart', 'Connection Before Correction Chart', 'kids'::resource_kind, 'A parent and child track moments of connecting first before a rule gets enforced, using simple stickers.', 'Use it to build the habit of connecting with a child before correcting their behavior.', array['Children', 'Adults']::text[], 'One week', 'The parent adds a sticker each time they pause to connect, a moment of eye contact, a calm tone, a named feeling, before giving a correction or consequence. The chart tracks the parent''s practice, not the child''s behavior, which keeps the focus where change is actually needed first. Review the week together and notice whether corrections landed differently on the days connection came first.', '[{"id": "f0", "type": "textarea", "label": "A moment I connected before correcting"}, {"id": "f1", "type": "textarea", "label": "What I did to connect"}, {"id": "f2", "type": "textarea", "label": "How the correction went afterward"}, {"id": "f3", "type": "textarea", "label": "What I want to practice more this week"}]'::jsonb, array['parenting', 'connection', 'children']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('realistic-expectations-by-age-worksheet', 'Realistic Expectations by Age Worksheet', 'worksheet'::resource_kind, 'Compares a parent''s current expectations for their child''s behavior against what is typical at that age.', 'Use it to separate a behavior that is a genuine concern from one that is simply age-typical.', array['Adults']::text[], '20 minutes', 'List the behaviors currently frustrating the parent, then look together at what is developmentally typical for the child''s age before deciding what actually needs a plan. Some behaviors will turn out to be ordinary and simply need patience rather than a strategy. This is psychoeducation, not a judgment on the parent''s instincts, and it helps to say that out loud.', '[{"id": "f0", "type": "textarea", "label": "A behavior that frustrates me"}, {"id": "f1", "type": "textarea", "label": "What I expected instead"}, {"id": "f2", "type": "textarea", "label": "What is typical for this age, as I understand it now"}, {"id": "f3", "type": "textarea", "label": "Whether this needs a plan or just patience"}]'::jsonb, array['parenting', 'child development', 'psychoeducation']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('parent-guilt-fact-check', 'Parent Guilt Fact-Check', 'cbt'::resource_kind, 'Tests a parent''s guilty thought about a parenting decision against the actual evidence available.', 'Use it to slow down a guilt spiral long enough to check it against reality.', array['Adults']::text[], '15 minutes', 'Write the guilty thought exactly as it occurred, then list what a fair, informed outsider would actually say about the decision, given everything the parent was working with at the time. Guilt often runs on an unfair, after-the-fact standard that ignores what information was available in the moment. Close by asking what the parent would tell a friend who made the same call.', '[{"id": "f0", "type": "textarea", "label": "The guilty thought"}, {"id": "f1", "type": "textarea", "label": "What I knew at the time I made the decision"}, {"id": "f2", "type": "textarea", "label": "What a fair outsider would say"}, {"id": "f3", "type": "textarea", "label": "What I would tell a friend in my exact situation"}]'::jsonb, array['parenting', 'guilt', 'cognitive restructuring']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('united-front-planning-session', 'United Front Planning Session', 'couples'::resource_kind, 'Has co-parents align on a response to a specific recurring behavior before the next time it happens.', 'Use it to reduce mid-conflict disagreement by planning the response together in advance.', array['Couples']::text[], '25 minutes', 'Pick one specific, recurring behavior rather than trying to align on everything at once, and agree on exactly what each parent will say and do the next time it happens. Address disagreement about the approach here, in a calm conversation, rather than in front of the child. Revisit after the plan has actually been used and adjust what did not work.', '[{"id": "f0", "type": "textarea", "label": "The specific behavior we are planning around"}, {"id": "f1", "type": "textarea", "label": "What Parent A will say and do"}, {"id": "f2", "type": "textarea", "label": "What Parent B will say and do"}, {"id": "f3", "type": "textarea", "label": "What we disagree about and how we resolved it"}, {"id": "f4", "type": "textarea", "label": "How the plan worked the first time we used it"}]'::jsonb, array['parenting', 'co-parenting', 'couples']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('family-meeting-agenda-game', 'Family Meeting Agenda Game', 'game'::resource_kind, 'A structured, turn-based family meeting format using a talking object and a simple agenda everyone helps set.', 'Use it to give every family member a predictable, fair turn to be heard.', array['Groups', 'Children', 'Adults']::text[], '20 minutes weekly', 'Set a short, consistent agenda, one win, one problem, one plan, from each family member, and pass a talking object so only the holder speaks. Keep the tone light and end on something the family did well that week. A meeting that runs long or turns into a lecture will not survive to the following week, so protect the time limit.', '[{"id": "f0", "type": "textarea", "label": "My win this week"}, {"id": "f1", "type": "textarea", "label": "A problem I want to raise"}, {"id": "f2", "type": "textarea", "label": "A plan I am proposing"}, {"id": "f3", "type": "textarea", "label": "Something our family did well this week"}]'::jsonb, array['parenting', 'family', 'communication']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('fourth-trimester-support-map', 'Fourth Trimester Support Map', 'worksheet'::resource_kind, 'Maps out concrete practical support, meals, errands, night help, a new parent has lined up for the weeks ahead.', 'Use it to make support specific and scheduled rather than a vague offer to let us know.', array['Adults']::text[], '20 minutes', 'Have the client name real people for each category, meals, errands, overnight help, emotional check-ins, rather than leaving gaps hoping someone will step in. A vague offer of help rarely turns into an actual delivered meal; a specific ask usually does. Revisit and update the map at two and six weeks, since needs shift fast in this period.', '[{"id": "f0", "type": "textarea", "label": "Who can bring meals"}, {"id": "f1", "type": "textarea", "label": "Who can run errands"}, {"id": "f2", "type": "textarea", "label": "Who can help overnight or with naps"}, {"id": "f3", "type": "textarea", "label": "Who I can call just to talk"}, {"id": "f4", "type": "textarea", "label": "One ask I have been avoiding making"}]'::jsonb, array['perinatal and postpartum', 'support network', 'planning']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('new-parent-guilt-thought-check', 'New Parent Guilt Thought Check', 'cbt'::resource_kind, 'Tests a new parent''s guilty thought about their adjustment against a fair, informed standard.', 'Use it to interrupt a guilt spiral common in the early weeks of parenthood.', array['Adults']::text[], '15 minutes', 'Write the exact guilty thought, then list what the client knew and had available at the time rather than judging it against an idealized standard seen online. Ask what a friend going through the same adjustment would be told. New parenthood runs on very little sleep and very high stakes, which itself deserves naming out loud.', '[{"id": "f0", "type": "textarea", "label": "The guilty thought"}, {"id": "f1", "type": "textarea", "label": "What was actually true about my situation at the time"}, {"id": "f2", "type": "textarea", "label": "What I would tell a friend in my exact spot"}, {"id": "f3", "type": "textarea", "label": "A more accurate thought"}]'::jsonb, array['perinatal and postpartum', 'guilt', 'cognitive restructuring']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('present-moment-with-the-baby-anchor', 'Present Moment With the Baby Anchor', 'act'::resource_kind, 'A short mindfulness practice for anchoring into a calm moment with the baby rather than the next worry.', 'Use it to build small pockets of presence inside an otherwise overwhelming stretch.', array['Adults']::text[], 'Five minutes', 'Pick one recurring moment, feeding, a diaper change, rocking, to practice noticing through the senses rather than mentally running the next task list. This is not meant to happen all day; a single anchored minute counts as a win. Some days there will be no room for it at all, and that is expected, not a failure.', '[{"id": "f0", "type": "textarea", "label": "The moment I chose to anchor into"}, {"id": "f1", "type": "textarea", "label": "What I noticed through my senses"}, {"id": "f2", "type": "textarea", "label": "What pulled my attention away"}, {"id": "f3", "type": "textarea", "label": "How it felt to have even one anchored minute"}]'::jsonb, array['perinatal and postpartum', 'mindfulness', 'present moment']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('splitting-the-mental-load-conversation', 'Splitting the Mental Load Conversation', 'couples'::resource_kind, 'Maps who currently tracks the invisible planning and remembering of new-baby life, not just the physical tasks.', 'Use it to make the mental load visible so it can be shared, not just the chores.', array['Couples']::text[], '25 minutes', 'List who currently remembers appointments, supply levels, feeding schedules and what the baby needs next, separate from who performs the physical task. Mental load imbalance is common and often invisible until named directly, so expect some surprise on one side. Agree on one category of tracking to hand off this week and check in on how the handoff went.', '[{"id": "f0", "type": "textarea", "label": "Who currently tracks appointments and schedules"}, {"id": "f1", "type": "textarea", "label": "Who currently tracks supplies and what is running low"}, {"id": "f2", "type": "textarea", "label": "What surprised us about this list"}, {"id": "f3", "type": "textarea", "label": "One category we are handing off this week"}]'::jsonb, array['perinatal and postpartum', 'mental load', 'couples']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('postpartum-wave-riding-card', 'Postpartum Wave Riding Card', 'dbt'::resource_kind, 'A DBT-style card for riding out a wave of postpartum overwhelm without judging it as failure.', 'Use it to help a new parent tolerate a hard wave of emotion until it passes.', array['Adults']::text[], 'Ten minutes', 'Name the wave as it is happening, out loud if possible, rather than fighting it or believing it will last forever. Pair it with one physical anchor, cold water, a slow exhale, a hand on the chest, that is realistic to use one-handed while holding a baby. Log afterward roughly how long the wave actually lasted, since overwhelmed minutes often feel far longer than they were.', '[{"id": "f0", "type": "textarea", "label": "What the wave felt like"}, {"id": "f1", "type": "textarea", "label": "My one-handed anchor"}, {"id": "f2", "type": "textarea", "label": "How long it actually lasted"}, {"id": "f3", "type": "textarea", "label": "What I want to remember next time a wave hits"}]'::jsonb, array['perinatal and postpartum', 'distress tolerance', 'regulation']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('unfair-comparison-spotting-log', 'Unfair Comparison Spotting Log', 'cbt'::resource_kind, 'Logs the specific comparisons a client makes against others and checks whether the comparison is actually fair.', 'Use it to catch comparisons that quietly stack the deck against the client.', array['Adults', 'Teens']::text[], 'One week', 'Have the client note who they compared themselves to and on what, then ask whether they were comparing their behind-the-scenes struggle to someone else''s highlight reel. Most logged comparisons turn out to be unfair on close inspection, comparing different starting points, different information, different seasons of life. Use the pattern to build one fairer comparison to replace an unfair habitual one.', '[{"id": "f0", "type": "textarea", "label": "Who I compared myself to"}, {"id": "f1", "type": "textarea", "label": "What I compared"}, {"id": "f2", "type": "textarea", "label": "Is this a fair comparison? Why or why not"}, {"id": "f3", "type": "textarea", "label": "A fairer comparison I could make instead"}]'::jsonb, array['self-esteem', 'social comparison', 'self-monitoring']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('multiple-selves-defusion-practice', 'Multiple Selves Defusion Practice', 'act'::resource_kind, 'Separates a client''s harsh, evaluative self-story from the fuller range of who they actually are.', 'Use it to loosen the grip of a single harsh self-story that gets treated as the whole truth.', array['Adults', 'Teens']::text[], '20 minutes', 'Ask the client to write the harsh story in one sentence, then list moments, however small, that do not fit that story cleanly. The point is not to argue the story is false, only that it is incomplete. Practice holding the story lightly, as one chapter rather than the whole book, especially in the moment it gets loud.', '[{"id": "f0", "type": "textarea", "label": "My harsh self-story, in one sentence"}, {"id": "f1", "type": "textarea", "label": "A moment that does not fit this story"}, {"id": "f2", "type": "textarea", "label": "Another moment that does not fit"}, {"id": "f3", "type": "textarea", "label": "What I want to remember when the story gets loud"}]'::jsonb, array['self-esteem', 'defusion', 'self-story']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('self-worth-inputs-audit-worksheet', 'Self-Worth Inputs Audit Worksheet', 'worksheet'::resource_kind, 'Lists where a client currently draws their sense of worth from, and how stable each source actually is.', 'Use it to find and diversify away from a single, fragile source of self-worth.', array['Adults', 'Teens']::text[], '25 minutes', 'List every current source of self-worth, performance, appearance, approval, achievements, and rate how stable and how within the client''s control each one is. A worth built on one unstable, uncontrollable source is fragile by design, not because the client is doing something wrong. Use the audit to identify one steadier, more controllable source to build up.', '[{"id": "f0", "type": "textarea", "label": "Source of self-worth 1 and how stable it is"}, {"id": "f1", "type": "textarea", "label": "Source of self-worth 2 and how stable it is"}, {"id": "f2", "type": "textarea", "label": "Source of self-worth 3 and how stable it is"}, {"id": "f3", "type": "textarea", "label": "One steadier source I want to build up"}]'::jsonb, array['self-esteem', 'self-worth', 'self-monitoring']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('my-growing-list-poster-craft', 'My Growing List Poster Craft', 'kids'::resource_kind, 'A child builds a poster that grows over weeks with things they have learned, tried or gotten better at.', 'Use it to give a child ongoing, visible evidence of growth rather than fixed praise.', array['Children']::text[], '20 minutes to start, ongoing to grow', 'The parent helps the child add to the poster regularly, focusing on effort and growth rather than only finished achievements, learning to tie a shoe, trying a hard food, asking for help. Praise the trying as much as the succeeding. Bring the poster to sessions occasionally so the child can show off their own record.', '[{"id": "f0", "type": "textarea", "label": "Something new I tried this week"}, {"id": "f1", "type": "textarea", "label": "Something I am getting better at"}, {"id": "f2", "type": "textarea", "label": "A time I asked for help"}, {"id": "f3", "type": "textarea", "label": "What I am proud of on my poster"}]'::jsonb, array['self-esteem', 'children', 'strengths']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('strengths-auction-game', 'Strengths Auction Game', 'game'::resource_kind, 'Players bid pretend currency on character strengths they most want to grow, then discuss why they chose them.', 'Use it to make naming and valuing personal strengths an active, engaging choice.', array['Groups', 'Teens']::text[], '25 minutes', 'Give each player a set amount of pretend currency and a list of strengths to bid on, letting players spend everything on one strength or spread it across several. Discuss why each person bid the way they did rather than treating the winning bids as the point. Close by asking which strength each player already has more of than they realized.', '[{"id": "f0", "type": "textarea", "label": "The strengths I bid on and how much"}, {"id": "f1", "type": "textarea", "label": "Why I chose them"}, {"id": "f2", "type": "textarea", "label": "A strength I already have more of than I realized"}]'::jsonb, array['self-esteem', 'strengths', 'play']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('post-mingling-memory-check', 'Post-Mingling Memory Check', 'cbt'::resource_kind, 'Compares a client''s memory of how a social event went against what a neutral observer likely would have seen.', 'Use it to correct a biased, overly harsh memory of a social event after the fact.', array['Adults', 'Teens']::text[], '15 minutes', 'Have the client write their memory of the event immediately after it, in detail, then return a day or two later to write it again from a more neutral, observer stance. The two versions are often strikingly different, and the gap is itself the useful finding. Use the comparison to question how reliable the client''s in-the-moment self-judgment tends to be.', '[{"id": "f0", "type": "textarea", "label": "My memory of the event right after it happened"}, {"id": "f1", "type": "textarea", "label": "My memory of the same event a couple days later, from an observer stance"}, {"id": "f2", "type": "textarea", "label": "What is different between the two"}, {"id": "f3", "type": "textarea", "label": "What this tells me about trusting my in-the-moment judgment"}]'::jsonb, array['social anxiety', 'cognitive restructuring', 'post-event processing']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('social-battery-pacing-card', 'Social Battery Pacing Card', 'dbt'::resource_kind, 'A DBT-style skills card for pacing social effort across an event rather than pushing until depletion.', 'Use it to build sustainable social stamina instead of all-or-nothing socializing.', array['Adults', 'Teens']::text[], '15 minutes', 'Plan a check-in point partway through an upcoming event to rate remaining social battery and decide whether to keep going, take a break, or leave. Normalize stepping outside briefly as a skill, not a failure or an escape. Track over several events whether pacing changes how the client feels the next day.', '[{"id": "f0", "type": "textarea", "label": "The event I am planning for"}, {"id": "f1", "type": "textarea", "label": "My check-in point during the event"}, {"id": "f2", "type": "textarea", "label": "My battery level at check-in"}, {"id": "f3", "type": "textarea", "label": "What I decided to do next"}, {"id": "f4", "type": "textarea", "label": "How I felt the next day compared to past events"}]'::jsonb, array['social anxiety', 'pacing', 'distress tolerance']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('imperfect-and-still-likeable-practice', 'Imperfect and Still Likeable Practice', 'act'::resource_kind, 'Tests the fused belief that any visible awkwardness will make a client unlikeable, through small experiments.', 'Use it to build willingness to be seen as imperfect in front of others.', array['Adults', 'Teens']::text[], '20 minutes', 'Plan one small, low-stakes moment of visible imperfection, a stumble in a sentence, asking a question that might sound obvious, and predict the fallout before trying it. Compare the prediction to what actually happened afterward. Repeated small experiments tend to move the belief further than any single conversation about it.', '[{"id": "f0", "type": "textarea", "label": "The small imperfect moment I planned"}, {"id": "f1", "type": "textarea", "label": "What I predicted would happen"}, {"id": "f2", "type": "textarea", "label": "What actually happened"}, {"id": "f3", "type": "textarea", "label": "What this experiment tells me about my fused belief"}]'::jsonb, array['social anxiety', 'willingness', 'defusion']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('would-you-rather-small-talk-edition', 'Would You Rather: Small Talk Edition', 'game'::resource_kind, 'A low-pressure would-you-rather game using social scenario questions to practice speaking up in a group.', 'Use it to practice speaking in a group on questions with no wrong answer.', array['Groups', 'Teens']::text[], '20 minutes', 'Use questions with genuinely no wrong answer, since the low stakes are the point, and let players pass to a neutral corner of the room if they cannot decide. Keep the pace quick so no one has time to overthink their turn. Debrief briefly on what it felt like to speak up in front of the group, since that is the actual skill being practiced.', '[{"id": "f0", "type": "textarea", "label": "A question I answered"}, {"id": "f1", "type": "textarea", "label": "My answer"}, {"id": "f2", "type": "textarea", "label": "How it felt to speak up in front of the group"}, {"id": "f3", "type": "textarea", "label": "What got easier as the game went on"}]'::jsonb, array['social anxiety', 'play', 'group']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('friend-making-script-cards', 'Friend-Making Script Cards', 'kids'::resource_kind, 'A child practices short, specific scripts for starting play with another child, using illustrated cue cards.', 'Use it to give a socially anxious child rehearsed, concrete words for approaching another kid.', array['Children']::text[], '20 minutes', 'The parent and child practice each script out loud, taking turns playing both roles, before the child tries it for real. Keep the scripts short and simple, one clear sentence a child can actually remember under nerves. Celebrate the attempt itself in the debrief afterward, whatever the other child''s response turned out to be.', '[{"id": "f0", "type": "textarea", "label": "My script for asking to join a game"}, {"id": "f1", "type": "textarea", "label": "My script for asking someone''s name"}, {"id": "f2", "type": "textarea", "label": "How my practice attempt went this week"}, {"id": "f3", "type": "textarea", "label": "What I want to try next time"}]'::jsonb, array['social anxiety', 'children', 'skills']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('what-i-still-do-because-of-you-list', 'What I Still Do Because of You List', 'worksheet'::resource_kind, 'Lists the habits, phrases and choices a client carries forward that came from the person who died.', 'Use it to make an ongoing bond visible rather than treating grief as something to move past entirely.', array['Adults', 'Teens']::text[], '20 minutes', 'List habits and phrases that clearly trace back to the person, a recipe, a saying, a way of greeting people, and let the client notice how much of that person is still present in daily life. This supports a continuing bond rather than a clean break, which fits how most people actually experience loss over time. Revisit the list as new entries occur to the client between sessions.', '[{"id": "f0", "type": "textarea", "label": "A habit I carry that came from them"}, {"id": "f1", "type": "textarea", "label": "A phrase or saying of theirs I still use"}, {"id": "f2", "type": "textarea", "label": "A choice I make differently because of them"}, {"id": "f3", "type": "textarea", "label": "One more I want to add later"}]'::jsonb, array['grief and loss', 'continuing bonds', 'reflection']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('grief-and-guilt-untangling-sheet', 'Grief and Guilt Untangling Sheet', 'cbt'::resource_kind, 'Separates a client''s grief from guilty thoughts about what they could have done differently.', 'Use it to test a guilty thought against what the client actually knew at the time.', array['Adults', 'Teens']::text[], '20 minutes', 'Write the guilty thought exactly as it runs, then list what the client actually knew and could have known at the time, not what is obvious only in hindsight. Hindsight bias runs strong in grief, and naming it directly can loosen a thought''s grip. Keep grief and guilt as two separate threads on the page, since they often get tangled into one.', '[{"id": "f0", "type": "textarea", "label": "The guilty thought"}, {"id": "f1", "type": "textarea", "label": "What I actually knew at the time"}, {"id": "f2", "type": "textarea", "label": "What is only obvious in hindsight"}, {"id": "f3", "type": "textarea", "label": "A more accurate thought"}]'::jsonb, array['grief and loss', 'guilt', 'cognitive restructuring']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('carrying-it-forward-values-practice', 'Carrying It Forward Values Practice', 'act'::resource_kind, 'Identifies a value the person who died embodied, and one way the client can carry that value forward.', 'Use it to give grief a forward-facing thread alongside the pain of the loss.', array['Adults', 'Teens']::text[], '20 minutes', 'Ask what the person valued or stood for, in the client''s own words, and explore one small, concrete way to live that value out this week. This is not about replacing the person or rushing past grief, only about finding one place grief and living forward can coexist. Return to it periodically rather than treating it as a single exercise.', '[{"id": "f0", "type": "textarea", "label": "A value this person embodied"}, {"id": "f1", "type": "textarea", "label": "How I want to carry that value forward"}, {"id": "f2", "type": "textarea", "label": "One small way I can live it out this week"}, {"id": "f3", "type": "textarea", "label": "How it feels to think about carrying this forward"}]'::jsonb, array['grief and loss', 'values', 'meaning']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('remembering-together-craft', 'Remembering Together Craft', 'kids'::resource_kind, 'A child makes a small craft, a drawing or collage, showing a favorite memory of someone who died.', 'Use it to give a grieving child a concrete way to hold and share a memory.', array['Children']::text[], '25 minutes', 'The parent sits with the child while they choose and create the memory, asking open questions rather than steering toward a particular emotion. Some children will want to talk while making it, others will work quietly, and both are fine. Keep the finished piece somewhere the child can revisit it, and let them decide whether to share it with others.', '[{"id": "f0", "type": "textarea", "label": "The memory I chose"}, {"id": "f1", "type": "textarea", "label": "What I made to show it"}, {"id": "f2", "type": "textarea", "label": "How I feel when I think about this memory"}, {"id": "f3", "type": "textarea", "label": "Who I want to show it to, if anyone"}]'::jsonb, array['grief and loss', 'children', 'memory']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('grieving-on-different-timelines-conversation', 'Grieving on Different Timelines Conversation', 'couples'::resource_kind, 'Helps a couple name and accept that each partner may be grieving the same loss on a different timeline.', 'Use it to reduce conflict that comes from expecting a partner''s grief to match one''s own.', array['Couples']::text[], '25 minutes', 'Have each partner describe where they currently are in their own grief, without comparing it to the other''s pace, since grief timelines rarely match even within the same loss. Ask what each partner needs from the other right now, which may be very different needs. Agree on one way to check in with each other going forward without either partner having to perform grief on a schedule.', '[{"id": "f0", "type": "textarea", "label": "Where I am in my grief right now"}, {"id": "f1", "type": "textarea", "label": "Where I sense my partner is in theirs"}, {"id": "f2", "type": "textarea", "label": "What I need from my partner right now"}, {"id": "f3", "type": "textarea", "label": "How we will check in with each other going forward"}]'::jsonb, array['grief and loss', 'couples', 'support']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('unmet-need-behind-the-complaint-sheet', 'Unmet Need Behind the Complaint Sheet', 'couples'::resource_kind, 'Traces a recurring complaint back to the specific, unmet need underneath it, for both partners.', 'Use it to move a couple from surface complaints to the needs actually driving them.', array['Couples']::text[], '25 minutes', 'Ask each partner to state a recurring complaint, then keep asking what need is not being met underneath it until something concrete emerges, being seen, feeling like a priority, having space. Complaints stated as needs are far easier for a partner to actually respond to than complaints stated as criticism. Practice restating one complaint as a need out loud before the session ends.', '[{"id": "f0", "type": "textarea", "label": "My recurring complaint"}, {"id": "f1", "type": "textarea", "label": "The need underneath it"}, {"id": "f2", "type": "textarea", "label": "My partner''s recurring complaint"}, {"id": "f3", "type": "textarea", "label": "The need underneath theirs"}, {"id": "f4", "type": "textarea", "label": "How I will restate my complaint as a need"}]'::jsonb, array['relationship issues', 'needs', 'communication']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('letting-go-of-being-right-practice', 'Letting Go of Being Right Practice', 'act'::resource_kind, 'Practices noticing the urge to win an argument and choosing connection instead, as a values-based act.', 'Use it to build willingness to prioritize the relationship over being proven correct.', array['Couples', 'Adults']::text[], '20 minutes', 'Ask the client to recall a recent argument and rate how much energy went into being right versus staying connected. Explore what being right actually costs when it comes at connection''s expense, and what the client values more in the relationship overall. This is not about giving up valid points, only about noticing the choice being made in the moment.', '[{"id": "f0", "type": "textarea", "label": "A recent argument where being right mattered a lot to me"}, {"id": "f1", "type": "textarea", "label": "What being right cost me in that moment"}, {"id": "f2", "type": "textarea", "label": "What I value more than winning that argument"}, {"id": "f3", "type": "textarea", "label": "What choosing connection would have looked like instead"}]'::jsonb, array['relationship issues', 'values', 'defusion']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('interpersonal-effectiveness-priority-check', 'Interpersonal Effectiveness Priority Check', 'dbt'::resource_kind, 'Weighs whether a relationship goal, an objective, the relationship or self-respect, matters most in a given conflict.', 'Use it to choose a communication strategy that matches what actually matters most right now.', array['Adults', 'Couples']::text[], '15 minutes', 'Walk through the situation and ask which priority matters most this time, getting the specific outcome, protecting the relationship, or keeping self-respect intact, since the right approach shifts depending on the answer. A client who always defaults to one priority regardless of the situation is worth naming that pattern to. Use the answer to choose which skills to lean on for this particular conversation.', '[{"id": "f0", "type": "textarea", "label": "The situation"}, {"id": "f1", "type": "textarea", "label": "My objective, if I have one"}, {"id": "f2", "type": "textarea", "label": "What matters most this time: outcome, relationship, or self-respect"}, {"id": "f3", "type": "textarea", "label": "What approach fits that priority"}]'::jsonb, array['relationship issues', 'interpersonal effectiveness', 'communication']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('mind-reading-interrupt-sheet', 'Mind-Reading Interrupt Sheet', 'cbt'::resource_kind, 'Catches a client''s assumptions about a partner''s thoughts or motives and checks them against what was actually said.', 'Use it to replace assumed motives with information actually gathered from the partner.', array['Adults', 'Couples']::text[], '15 minutes', 'Write down the assumption about the partner''s thinking exactly as it occurred, then write what the partner actually said or did, separate from the interpretation layered on top. Most assumptions turn out to be untested guesses dressed up as facts. Practice one question the client could ask instead of assuming, and use it before the next conversation.', '[{"id": "f0", "type": "textarea", "label": "What I assumed my partner was thinking"}, {"id": "f1", "type": "textarea", "label": "What my partner actually said or did"}, {"id": "f2", "type": "textarea", "label": "The gap between the two"}, {"id": "f3", "type": "textarea", "label": "A question I could ask instead of assuming"}]'::jsonb, array['relationship issues', 'assumptions', 'communication']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('relationship-non-negotiables-worksheet', 'Relationship Non-Negotiables Worksheet', 'worksheet'::resource_kind, 'Separates a client''s true non-negotiables in a relationship from preferences they can flex on.', 'Use it to clarify what actually needs to hold firm versus what is open to compromise.', array['Adults']::text[], '25 minutes', 'List everything currently causing friction, then sort each item into a true non-negotiable or a preference that could flex, and push back gently on anything labeled non-negotiable without a clear reason why. A list where everything is non-negotiable usually needs more sorting, not validation. Use the finished list to decide where energy for negotiation is actually worth spending.', '[{"id": "f0", "type": "textarea", "label": "Something currently causing friction"}, {"id": "f1", "type": "textarea", "label": "Is it a true non-negotiable or a flexible preference?"}, {"id": "f2", "type": "textarea", "label": "Why it belongs in that category"}, {"id": "f3", "type": "textarea", "label": "One item I am willing to negotiate on"}]'::jsonb, array['relationship issues', 'boundaries', 'clarity']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('body-ownership-affirmation-sheet', 'Body Ownership Affirmation Sheet', 'worksheet'::resource_kind, 'Builds a short list of present-day statements affirming a client''s ownership and authority over their own body.', 'Use it to reinforce bodily autonomy in the present, without revisiting what happened.', array['Adults', 'Teens']::text[], '15 minutes', 'Write the statements in the client''s own words and voice, keeping them about today and going forward rather than about the past. Practice reading them aloud in session, since saying them out loud often lands differently than reading silently. This is a present-focused affirmation tool, not an invitation to describe any past event.', '[{"id": "f0", "type": "textarea", "label": "A statement about my right to say no"}, {"id": "f1", "type": "textarea", "label": "A statement about who gets to touch my body"}, {"id": "f2", "type": "textarea", "label": "A statement about trusting my own signals"}, {"id": "f3", "type": "textarea", "label": "Where I will keep these statements"}]'::jsonb, array['sexual abuse', 'boundaries', 'self-affirmation']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('self-blame-interrupt-sheet', 'Self-Blame Interrupt Sheet', 'cbt'::resource_kind, 'Interrupts a self-blaming thought by comparing it against what a survivor is actually responsible for.', 'Use it to redirect responsibility for what happened away from the client and toward the person who harmed them.', array['Adults', 'Teens']::text[], '20 minutes', 'Write the self-blaming thought exactly as it occurs, then list, plainly, who holds responsibility for causing harm versus who does not. Keep this grounded in the present, working with the belief itself rather than asking the client to recount events. A thought that shifts even slightly toward accurate responsibility is real progress, not a fixed outcome to reach in one sitting.', '[{"id": "f0", "type": "textarea", "label": "The self-blaming thought"}, {"id": "f1", "type": "textarea", "label": "Who actually holds responsibility for causing harm"}, {"id": "f2", "type": "textarea", "label": "What I am not responsible for"}, {"id": "f3", "type": "textarea", "label": "A more accurate thought I am willing to try on"}]'::jsonb, array['sexual abuse', 'shame', 'self-blame']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('choosing-safety-now-practice', 'Choosing Safety Now Practice', 'act'::resource_kind, 'Practices making one small, values-based choice about safety and boundaries in the client''s life today.', 'Use it to build a felt sense of agency and choice in the present.', array['Adults', 'Teens']::text[], '15 minutes', 'Ask about a current, everyday situation where the client can exercise choice around safety or boundaries, and rehearse making that choice in session. This stays entirely about the present and future; it is not a space for describing what happened before. Repeat with new, small choices over time to build the practiced experience of agency.', '[{"id": "f0", "type": "textarea", "label": "A present-day situation where I can choose safety"}, {"id": "f1", "type": "textarea", "label": "The choice I am making"}, {"id": "f2", "type": "textarea", "label": "How it feels to make this choice on purpose"}, {"id": "f3", "type": "textarea", "label": "Another small choice I want to practice next"}]'::jsonb, array['sexual abuse', 'safety', 'agency']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('grounding-menu-for-hard-moments', 'Grounding Menu for Hard Moments', 'dbt'::resource_kind, 'Builds a personalized menu of grounding skills a client can turn to when flooded or dissociating.', 'Use it to have a ready set of grounding options rather than searching for one under stress.', array['Adults', 'Teens']::text[], '20 minutes', 'Build the menu with a range of options, quick and slow, so the client has something for a two-minute break and something for a longer reset. Test each one in session while regulated, since a skill practiced calm works better under real stress. Keep the tool focused on present-moment grounding rather than processing content.', '[{"id": "f0", "type": "textarea", "label": "A quick grounding option, under two minutes"}, {"id": "f1", "type": "textarea", "label": "A longer grounding option"}, {"id": "f2", "type": "textarea", "label": "A grounding option I can use around other people"}, {"id": "f3", "type": "textarea", "label": "Which one I want to try first this week"}]'::jsonb, array['sexual abuse', 'grounding', 'distress tolerance']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('partner-pace-and-consent-check-in-script', 'Partner Pace and Consent Check-In Script', 'couples'::resource_kind, 'A short, repeatable script for a couple to check pace and consent around physical closeness.', 'Use it to give both partners a low-pressure, ongoing way to check in about pace.', array['Couples']::text[], '20 minutes', 'Build a plain, specific check-in phrase either partner can use at any point, and agree in advance that using it is always honored without question or negotiation in the moment. Practice saying the phrase out loud together so it feels familiar rather than awkward when it is actually needed. Revisit the script periodically as comfort and pace shift over time.', '[{"id": "f0", "type": "textarea", "label": "Our check-in phrase"}, {"id": "f1", "type": "textarea", "label": "What happens when either of us uses it"}, {"id": "f2", "type": "textarea", "label": "How we will practice this before we need it"}, {"id": "f3", "type": "textarea", "label": "One thing we agree never happens without a clear yes"}]'::jsonb, array['sexual abuse', 'consent', 'couples']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('five-minute-reset-menu-card', 'Five-Minute Reset Menu Card', 'dbt'::resource_kind, 'A quick-reference card of coping options a client can complete in five minutes or less.', 'Use it to have a low-barrier option ready for moments with little time or energy.', array['Adults', 'Teens']::text[], '15 minutes', 'Fill the card with options that genuinely take five minutes or less and require no special equipment, since a coping plan that needs too much setup will not get used in a rushed moment. Test each one for real before finalizing the card. Keep the card somewhere it will actually be seen, a phone lock screen or a wallet, rather than filed away.', '[{"id": "f0", "type": "textarea", "label": "A reset I can do in under a minute"}, {"id": "f1", "type": "textarea", "label": "A reset I can do in two to five minutes"}, {"id": "f2", "type": "textarea", "label": "Where I will keep this card"}, {"id": "f3", "type": "textarea", "label": "One I tested this week and how it went"}]'::jsonb, array['coping skills', 'quick reference', 'planning']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('coping-versus-avoiding-sort', 'Coping Versus Avoiding Sort', 'act'::resource_kind, 'Sorts a client''s go-to strategies into ones that help them face life and ones that mainly help them dodge it.', 'Use it to tell the difference between a coping skill and an avoidance strategy wearing its clothes.', array['Adults', 'Teens']::text[], '20 minutes', 'List current go-to strategies honestly, including the ones the client is not proud of, and sort each by whether it moves them toward their life or mainly away from a feeling. Some strategies belong in both columns depending on how they are used, which is itself worth discussing. The goal is not to eliminate every avoidance strategy, only to see clearly which is which.', '[{"id": "f0", "type": "textarea", "label": "A strategy I use often"}, {"id": "f1", "type": "textarea", "label": "Does it move me toward my life or away from a feeling?"}, {"id": "f2", "type": "textarea", "label": "Another strategy"}, {"id": "f3", "type": "textarea", "label": "Does it move me toward my life or away from a feeling?"}, {"id": "f4", "type": "textarea", "label": "One strategy I want to use more of"}]'::jsonb, array['coping skills', 'avoidance', 'willingness']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('coping-skills-pictionary-round', 'Coping Skills Pictionary Round', 'game'::resource_kind, 'Players draw a coping skill without words or numbers while the group guesses what it is.', 'Use it to build familiarity with a wide range of coping skills through active recall.', array['Groups', 'Teens', 'Children']::text[], '20 minutes', 'Prepare a deck of specific coping skills and let players draw quietly while the group calls out guesses. A skill that is hard to draw is often a good prompt for discussion about how it actually works, not just what it looks like. Close by asking which drawn skill the group wants to try together before the session ends.', '[{"id": "f0", "type": "textarea", "label": "A coping skill I drew or guessed"}, {"id": "f1", "type": "textarea", "label": "How I would actually use this skill"}, {"id": "f2", "type": "textarea", "label": "One skill from the game I want to try this week"}]'::jsonb, array['coping skills', 'play', 'group']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('coping-tree-craft', 'Coping Tree Craft', 'kids'::resource_kind, 'A child builds a paper tree where each leaf names one thing that helps them feel better.', 'Use it to give a child a growing, visible collection of their own coping skills.', array['Children']::text[], '20 minutes to start, ongoing to grow', 'The parent helps the child add a new leaf whenever they discover something that helps, so the tree grows over weeks rather than being finished in one sitting. Keep leaves specific, a song, a hug, a certain blanket, rather than vague. Hang the tree somewhere the child can point to a leaf when they need an idea in the moment.', '[{"id": "f0", "type": "textarea", "label": "A leaf for something that calms me down"}, {"id": "f1", "type": "textarea", "label": "A leaf for something that makes me feel brave"}, {"id": "f2", "type": "textarea", "label": "A leaf for someone who helps me feel better"}, {"id": "f3", "type": "textarea", "label": "The next leaf I want to add"}]'::jsonb, array['coping skills', 'children', 'self-soothing']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('coping-skill-access-cost-worksheet', 'Coping Skill Access Cost Worksheet', 'worksheet'::resource_kind, 'Rates each of a client''s coping skills by how easy it actually is to access in the moment it is needed.', 'Use it to favor coping skills that are realistically available over ones that only work in theory.', array['Adults', 'Teens']::text[], '20 minutes', 'List current coping skills and rate each on how much setup, privacy or equipment it actually requires, since a skill that needs all three is unlikely to get used during a rough morning at work. Sort the list by access cost from lowest to highest. Build a short list of the lowest-cost options to lean on when time and privacy are limited.', '[{"id": "f0", "type": "textarea", "label": "A coping skill I use"}, {"id": "f1", "type": "textarea", "label": "What it requires to access (time, privacy, equipment)"}, {"id": "f2", "type": "textarea", "label": "How realistic that is on a hard day"}, {"id": "f3", "type": "textarea", "label": "My three lowest-cost, most realistic options"}]'::jsonb, array['coping skills', 'planning', 'self-monitoring']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('feared-outcome-reality-check-log', 'Feared Outcome Reality Check Log', 'cbt'::resource_kind, 'Logs a client''s predicted feared outcome against the far more mundane thing that usually actually happens.', 'Use it to build evidence, over time, that the feared object rarely delivers the predicted catastrophe.', array['Adults', 'Teens']::text[], 'One week', 'Before each exposure or encounter, write the specific feared outcome and a confidence rating, then log the actual outcome immediately after. Resist smoothing over a close call; log it exactly as it happened. Tally the pattern together at the end of the week rather than letting any single dramatic entry dominate the conversation.', '[{"id": "f0", "type": "textarea", "label": "The feared object or situation"}, {"id": "f1", "type": "textarea", "label": "My predicted outcome"}, {"id": "f2", "type": "textarea", "label": "My confidence in that prediction, zero to ten"}, {"id": "f3", "type": "textarea", "label": "What actually happened"}, {"id": "f4", "type": "textarea", "label": "How accurate my prediction turned out to be"}]'::jsonb, array['phobias', 'prediction', 'exposure']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('approach-with-willingness-practice', 'Approach With Willingness Practice', 'act'::resource_kind, 'Practices approaching a feared object or situation while making room for fear rather than waiting for it to go away first.', 'Use it to decouple taking an approach step from needing fear to be absent first.', array['Adults', 'Teens']::text[], '20 minutes', 'Rate willingness to approach separately from fear level before and after a step, and point out when willingness rose even though fear did not fall, since that gap is the actual skill being built. Choose an approach step collaboratively rather than assigning one, so the client has genuine ownership of the pace. Avoid promising the fear will disappear; promise only that it does not have to be gone to take the step.', '[{"id": "f0", "type": "textarea", "label": "The step I am willing to try"}, {"id": "f1", "type": "textarea", "label": "My fear level before, zero to ten"}, {"id": "f2", "type": "textarea", "label": "My willingness level before, zero to ten"}, {"id": "f3", "type": "textarea", "label": "My fear level after"}, {"id": "f4", "type": "textarea", "label": "My willingness level after"}]'::jsonb, array['phobias', 'willingness', 'exposure']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('fear-sensation-tolerance-card', 'Fear Sensation Tolerance Card', 'dbt'::resource_kind, 'A skills card for tolerating the physical sensations of fear during an approach step without escaping early.', 'Use it to build tolerance for fear''s physical sensations long enough to stay in the situation.', array['Adults', 'Teens']::text[], '15 minutes', 'Name the specific body sensations that show up, racing heart, sweating, shaking, and pick one grounding action to pair with staying rather than leaving. Practice describing the sensations out loud during a mild version of the fear before relying on the skill for a bigger step. Track how long the sensations actually lasted against how long the client expected them to.', '[{"id": "f0", "type": "textarea", "label": "The sensations I notice"}, {"id": "f1", "type": "textarea", "label": "My grounding action for staying"}, {"id": "f2", "type": "textarea", "label": "How long the sensations actually lasted"}, {"id": "f3", "type": "textarea", "label": "How that compares to what I expected"}]'::jsonb, array['phobias', 'distress tolerance', 'exposure']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('brave-steps-sticker-trail-craft', 'Brave Steps Sticker Trail Craft', 'kids'::resource_kind, 'A child builds a paper trail of stickers, each one marking a small brave step toward a feared thing.', 'Use it to make a step-by-step approach to a fear visible and rewarding for a child.', array['Children']::text[], '20 minutes to build, ongoing to fill', 'The parent and child plan the steps together first, from easiest to hardest, before adding any stickers, so the trail matches a real, workable plan rather than being decorated after the fact. Celebrate each step as it happens rather than only the final one. Let the child set the pace for how many stickers get added in a week.', '[{"id": "f0", "type": "textarea", "label": "My first small step"}, {"id": "f1", "type": "textarea", "label": "My next step"}, {"id": "f2", "type": "textarea", "label": "My biggest step, saved for later"}, {"id": "f3", "type": "textarea", "label": "How I felt after my last sticker"}]'::jsonb, array['phobias', 'children', 'exposure']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('fear-ladder-board-race', 'Fear Ladder Board Race', 'game'::resource_kind, 'Players move a token up a shared game board by naming and normalizing common fears along the way.', 'Use it to normalize having fears through a light, shared group format.', array['Groups', 'Children', 'Teens']::text[], '20 minutes', 'Players land on spaces naming common fears and share, briefly, whether they relate, with passing always allowed. The game works because it makes having a fear ordinary rather than something to hide, especially in a group setting. Close by asking whether hearing other people''s fears changed how big anyone''s own fear felt.', '[{"id": "f0", "type": "textarea", "label": "A fear I shared during the game"}, {"id": "f1", "type": "textarea", "label": "A fear someone else shared that I related to"}, {"id": "f2", "type": "textarea", "label": "Whether the game changed how big my fear feels"}]'::jsonb, array['phobias', 'psychoeducation', 'play']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('appearance-focused-time-audit', 'Appearance-Focused Time Audit', 'cbt'::resource_kind, 'Logs how much time in a day goes toward appearance-checking behaviors, compared to what the client would choose.', 'Use it to make the time cost of appearance-checking visible and open to change.', array['Adults', 'Teens']::text[], 'One week', 'Have the client log each appearance-checking moment, mirrors, reflections, photos, without judgment attached to the entry itself. Total the week''s time and compare it to how the client would rather have spent those minutes. The goal is informed choice, not shame about the current pattern, so keep the tone factual throughout.', '[{"id": "f0", "type": "textarea", "label": "An appearance-checking moment today"}, {"id": "f1", "type": "textarea", "label": "Roughly how long it took"}, {"id": "f2", "type": "textarea", "label": "What I would rather have been doing"}, {"id": "f3", "type": "textarea", "label": "This week''s rough total"}]'::jsonb, array['body image', 'self-monitoring', 'habits']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('body-as-home-not-ornament-practice', 'Body as Home, Not Ornament Practice', 'act'::resource_kind, 'Shifts attention from how the body looks to what it lets the client do, feel and experience each day.', 'Use it to build a functional, lived relationship with the body alongside the appearance-focused one.', array['Adults', 'Teens']::text[], '15 minutes', 'Ask what the body allowed the client to do today, carry something, laugh, hug someone, walk somewhere, separate entirely from how it looked while doing it. Some clients find this hard at first; a single functional moment is enough to start. Practice noticing function throughout an ordinary day, not only during the exercise itself.', '[{"id": "f0", "type": "textarea", "label": "Something my body let me do today"}, {"id": "f1", "type": "textarea", "label": "Something my body let me feel today"}, {"id": "f2", "type": "textarea", "label": "A moment my body carried me through something hard"}, {"id": "f3", "type": "textarea", "label": "What I want to notice more of this week"}]'::jsonb, array['body image', 'acceptance', 'function']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('media-message-awareness-worksheet', 'Media Message Awareness Worksheet', 'worksheet'::resource_kind, 'Tracks the appearance messages a client absorbs from media in a day and how each one lands afterward.', 'Use it to build awareness of appearance messaging the client is exposed to and its actual effect.', array['Adults', 'Teens']::text[], 'One week', 'Log a few examples of appearance-related media encountered in a day, an ad, a post, a show, and rate mood immediately after seeing each one. Patterns often emerge quickly between certain kinds of content and a mood dip. Use the pattern to make one deliberate choice about media use this week, rather than a blanket rule.', '[{"id": "f0", "type": "textarea", "label": "A piece of media I encountered"}, {"id": "f1", "type": "textarea", "label": "The appearance message it sent"}, {"id": "f2", "type": "textarea", "label": "How I felt right after seeing it"}, {"id": "f3", "type": "textarea", "label": "One choice I want to make about my media use this week"}]'::jsonb, array['body image', 'media', 'self-monitoring']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('supporting-without-commenting-script', 'Supporting Without Commenting Script', 'couples'::resource_kind, 'Helps a partner learn to support a client through body image struggles without commenting on appearance at all.', 'Use it to give a partner a way to be supportive that does not rely on appearance-based reassurance.', array['Couples']::text[], '20 minutes', 'Ask the client what kind of support actually helps, being asked how they are feeling, a distraction, a hand held, rather than comments about how they look, which can backfire even when meant kindly. Have the partner practice offering exactly that instead. Agree on a signal the client can use when appearance comments, even well-meant ones, are not landing well.', '[{"id": "f0", "type": "textarea", "label": "What actually helps me on a hard body image day"}, {"id": "f1", "type": "textarea", "label": "What does not help, even if well-meant"}, {"id": "f2", "type": "textarea", "label": "What my partner will say or do instead"}, {"id": "f3", "type": "textarea", "label": "A signal I can use if a comment does not land well"}]'::jsonb, array['body image', 'support', 'couples']::text[], '2026-09-22T15:00:00+00:00'::timestamptz),
  ('nonjudgmental-body-noticing-card', 'Nonjudgmental Body Noticing Card', 'dbt'::resource_kind, 'Practices describing body sensations and appearance thoughts factually, without the usual judgment attached.', 'Use it to build the skill of observing the body without the automatic evaluative commentary.', array['Adults', 'Teens']::text[], '15 minutes', 'Practice describing what is noticed in purely factual terms, this is my hand, it is resting on the table, rather than good or bad, and catch judgmental words as they show up, swapping them for neutral ones. This is a skill built through repeated short practice, not a single insight. Use it especially in moments an appearance thought would normally take over.', '[{"id": "f0", "type": "textarea", "label": "A judgmental thought I caught about my body"}, {"id": "f1", "type": "textarea", "label": "A neutral, factual way to describe the same thing"}, {"id": "f2", "type": "textarea", "label": "A moment I want to practice this skill next"}]'::jsonb, array['body image', 'nonjudgmental stance', 'mindfulness']::text[], '2026-09-22T15:00:00+00:00'::timestamptz)
